window.BRIDGE_PAGE_SOURCES=[{"name": "fem-workbench.html", "text": "<!doctype html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>车停在哪里，桥面会有什么不同？</title><link rel=\"stylesheet\" href=\"fem-workbench.css\"></head><body>\n<header><a href=\"../bridge-thinking.html\">← 拓展篇</a><strong>桥面实验场</strong><a href=\"plate-chain.html\">计算原理与板梁对照</a></header>\n<div class=\"workbench\">\n<aside class=\"tasks\"><h1>操作，就是答题</h1><p class=\"muted\">10 个示范任务 · 第 11 章拓展<br>当前示范为平直板的线弹性响应</p><label>任务<select id=\"task\"></select></label><h2 id=\"taskTitle\"></h2><p id=\"taskPrompt\"></p><button id=\"start\">准备本题</button><button id=\"submit\">核对本题</button><p id=\"feedback\" role=\"status\">选择任务后，点击准备本题。</p><label>我的解释<textarea id=\"explain\" rows=\"3\" placeholder=\"我改变了什么？凭什么判断？\"></textarea></label><button id=\"save\" class=\"secondary\">导出操作与证据</button><p id=\"progress\"></p><details><summary>看关键代码</summary><pre>result = solve(parameters);\nnode.w = result.w[node.id];\ndisplay.z = scale * node.w;\ngrade(result, task.rules);</pre><p>旋转相机与显示放大不改变 result。完整求解和绘图代码见页尾。</p></details></aside>\n<section class=\"visual\"><div class=\"toolbar\"><button id=\"home\">轴测</button><button id=\"top\">俯视</button><button id=\"side\">侧视</button><button id=\"fullscreen\">全屏画面</button><label>显示放大 <input id=\"scale\" type=\"range\" min=\"0\" max=\"200\" value=\"100\" step=\"10\"><output id=\"scaleOut\">100×</output></label></div><div id=\"scene\" tabindex=\"0\" aria-label=\"三维桥面板。拖动旋转，滚轮缩放，点击节点取样。方向键旋转，加减键缩放。\"><div class=\"legend\"><span>−12 mm 下挠</span><i></i><span>+12 mm 上翘</span></div><div id=\"sceneNote\">正在建立三维视图…</div></div><div class=\"readouts\"><div><small>选中节点 · 同一求解数据</small><strong id=\"node\">—</strong></div><div><small>该节点 w</small><strong id=\"w\">—</strong></div><div><small>全模型节点最小 w</small><strong id=\"min\">—</strong></div><div><small>竖向力平衡相对残差</small><strong id=\"balance\">—</strong></div></div><div id=\"status\" role=\"status\">等待求解</div></section>\n<aside class=\"parameters\"><h2>物理参数</h2><label>桥面怎样被托住<select id=\"mode\"><option value=\"full\">两跨连续板</option><option value=\"simple\">左跨简支板</option></select></label><label>荷载<select id=\"load\"><option value=\"uniform\">两跨全宽均布</option><option value=\"patch\">左跨有限面荷载</option></select></label><label>基准压力 p / kPa<input id=\"pressure\" type=\"number\" min=\"2\" max=\"20\" step=\"0.5\" value=\"10\"></label><label>板宽 B / m<select id=\"width\"><option>1</option><option selected>3</option><option>6</option></select></label><label>泊松比 ν<select id=\"nu\"><option>0</option><option selected>0.2</option><option>0.3</option></select></label><label>每跨网格<select id=\"mesh\"><option value=\"4\">4 × 4</option><option value=\"8\" selected>8 × 8</option><option value=\"12\">12 × 12</option><option value=\"16\">16 × 16</option></select></label><label>面荷载起点 x/L<select id=\"patchX\"><option value=\"0\">0</option><option value=\"0.125\">0.125</option><option value=\"0.25\" selected>0.25</option><option value=\"0.375\">0.375</option><option value=\"0.5\">0.5</option></select></label><label>面荷载起点 y/B<select id=\"patchY\"><option value=\"0\" selected>0</option><option value=\"0.25\">0.25</option><option value=\"0.5\">0.5</option></select></label><button id=\"calculate\">应用参数并计算</button><p class=\"muted\">固定 L=4 m、t=0.16 m、E=30 GPa。面荷载范围为 L/2 × B/2、压力 4p，总力始终 pLB。移动面荷载采用 8 或 16 网格保持边界对齐；切换后会自动对齐。无自重。色标固定 ±12 mm，超出范围饱和显示，数值保留实际值。</p></aside>\n</div><section class=\"sources\"><details><summary>模型范围与结果一致性</summary><p>三维坐标由同一节点表与位移表生成，板跨向 x、板宽方向 y、竖向 z（小车场景的 y 沿主梁方向）；展示映射至 Three.js 的 (x,z,−y)。显示变形为 z=放大倍数×w。旋转和缩放只改变相机。点击节点、方向视图、数字读数与题目核对均引用当前结果；网格与求解版本写入导出记录。节点位移着色采用插值显示，不是应力图。求解在本地 Web Worker 执行。</p><p>平直小变形线弹性 MITC4；仅竖向荷载，面内及钻转自由度固定，线支承限制 w，未建模支承脱空、开裂、曲率膜作用或动力效应。面荷载起点限定在给定网格内；“最不利”只针对指定节点的最小 w 与指定的 15 个位置，不宣称连续域或规范荷载组合的全局最优。调参成功仅代表教学任务达标。</p><p><a href=\"plate-chain/verification.json\">有限元数值验证记录</a> · <a href=\"../core-resources.html\">11 章 × 10 个已有学习单元与自测</a> · <a href=\"ch04-arch-lab.html\">拱桥组合有限元</a> · <a href=\"ch10-bridge-section-spatial-lab.html\">空间截面旋转匹配</a> · <a href=\"ch03-continuous-loading.html\">正负影响线不利布载</a></p></details></section>\n<script src=\"plate-chain/worker-source.js\"></script><script src=\"bundles/fem-workbench.bundle.js\"></script>\n</body></html>\n"}, {"name": "interactive/plate-chain/worker-source.js", "text": "window.PLATE_WORKER_SOURCE=\"// Generated by scripts/build_plate_solver.py; edit shell-element.mjs.\\n(()=>{\\n/**\\n * Educational four-node flat-shell element for browser FEM prototypes.\\n *\\n * Formulation:\\n * - bilinear Q4 plane-stress membrane\\n * - Reissner-Mindlin bending and transverse shear\\n * - MITC4 tying-point interpolation for transverse shear\\n * - compatible drilling-rotation penalty\\n * - 6 global DOF/node: [ux, uy, uz, rx, ry, rz]\\n *\\n * Scope: small-strain, linear-elastic, planar quadrilateral shells. This is a\\n * transparent teaching implementation, not a replacement for a production\\n * MITC4/S4R element in OpenSees, Abaqus, ANSYS, or another verified solver.\\n */\\n\\nconst DOF_PER_NODE = 6;\\nconst DOF_NAMES = ['ux', 'uy', 'uz', 'rx', 'ry', 'rz'];\\n\\nconst EPS = 1e-12;\\nconst GAUSS = 1 / Math.sqrt(3);\\n\\nfunction zeros(rows, cols = rows) {\\n  return Array.from({ length: rows }, () => new Float64Array(cols));\\n}\\n\\nfunction vecZeros(n) {\\n  return new Float64Array(n);\\n}\\n\\nfunction dot(a, b) {\\n  return a[0] * b[0] + a[1] * b[1] + a[2] * b[2];\\n}\\n\\nfunction sub(a, b) {\\n  return [a[0] - b[0], a[1] - b[1], a[2] - b[2]];\\n}\\n\\nfunction cross(a, b) {\\n  return [\\n    a[1] * b[2] - a[2] * b[1],\\n    a[2] * b[0] - a[0] * b[2],\\n    a[0] * b[1] - a[1] * b[0],\\n  ];\\n}\\n\\nfunction norm(a) {\\n  return Math.sqrt(dot(a, a));\\n}\\n\\nfunction normalize(a, label) {\\n  const n = norm(a);\\n  if (n < EPS) throw new Error(`${label} has near-zero length`);\\n  return a.map((v) => v / n);\\n}\\n\\nfunction toPoint(node) {\\n  return [Number(node.x), Number(node.y ?? 0), Number(node.z ?? 0)];\\n}\\n\\nfunction checkShellInput(nodes, material) {\\n  if (!Array.isArray(nodes) || nodes.length !== 4) {\\n    throw new Error('shell4 requires four nodes ordered counter-clockwise');\\n  }\\n  for (const [i, node] of nodes.entries()) {\\n    const p = toPoint(node);\\n    if (!p.every(Number.isFinite)) throw new Error(`shell4 node ${i} is invalid`);\\n  }\\n  const { E, nu, t } = material;\\n  if (!(E > 0)) throw new Error('shell4 material E must be positive');\\n  if (!(t > 0)) throw new Error('shell4 thickness t must be positive');\\n  if (!(nu > -0.999 && nu < 0.499)) {\\n    throw new Error('shell4 Poisson ratio nu must be between -0.999 and 0.499');\\n  }\\n}\\n\\n/** Build a local right-handed frame. Nodes must be approximately coplanar. */\\nfunction shellLocalFrame(nodes, planarityTolerance = 1e-5) {\\n  const p = nodes.map(toPoint);\\n  const ex = normalize(sub(p[1], p[0]), 'shell local x axis');\\n  const normalSeed = cross(sub(p[1], p[0]), sub(p[3], p[0]));\\n  const ez = normalize(normalSeed, 'shell normal');\\n  const ey = normalize(cross(ez, ex), 'shell local y axis');\\n  const edgeLengths = [\\n    norm(sub(p[1], p[0])), norm(sub(p[2], p[1])),\\n    norm(sub(p[3], p[2])), norm(sub(p[0], p[3])),\\n  ];\\n  const lengthScale = Math.max(...edgeLengths, 1);\\n  const warping = Math.max(...p.map((point) => Math.abs(dot(sub(point, p[0]), ez))));\\n  if (warping > planarityTolerance * lengthScale) {\\n    throw new Error(\\n      `shell4 is not planar: warping=${warping.toExponential(3)}, ` +\\n      `limit=${(planarityTolerance * lengthScale).toExponential(3)}`,\\n    );\\n  }\\n  const localXY = p.map((point) => {\\n    const d = sub(point, p[0]);\\n    return [dot(d, ex), dot(d, ey)];\\n  });\\n  return { origin: p[0], ex, ey, ez, localXY, warping, lengthScale };\\n}\\n\\nfunction q4Shape(xi, eta) {\\n  return {\\n    N: new Float64Array([\\n      0.25 * (1 - xi) * (1 - eta),\\n      0.25 * (1 + xi) * (1 - eta),\\n      0.25 * (1 + xi) * (1 + eta),\\n      0.25 * (1 - xi) * (1 + eta),\\n    ]),\\n    dXi: new Float64Array([\\n      -0.25 * (1 - eta), 0.25 * (1 - eta),\\n      0.25 * (1 + eta), -0.25 * (1 + eta),\\n    ]),\\n    dEta: new Float64Array([\\n      -0.25 * (1 - xi), -0.25 * (1 + xi),\\n      0.25 * (1 + xi), 0.25 * (1 - xi),\\n    ]),\\n  };\\n}\\n\\n/** Return shape data and Cartesian derivatives for a Q4 point. */\\nfunction q4Geometry(localXY, xi, eta) {\\n  const { N, dXi, dEta } = q4Shape(xi, eta);\\n  let xXi = 0, yXi = 0, xEta = 0, yEta = 0;\\n  for (let i = 0; i < 4; i++) {\\n    xXi += dXi[i] * localXY[i][0];\\n    yXi += dXi[i] * localXY[i][1];\\n    xEta += dEta[i] * localXY[i][0];\\n    yEta += dEta[i] * localXY[i][1];\\n  }\\n  const detJ = xXi * yEta - yXi * xEta;\\n  if (!(detJ > EPS)) {\\n    throw new Error(`shell4 has non-positive Jacobian detJ=${detJ}`);\\n  }\\n  const inv00 = yEta / detJ;\\n  const inv01 = -yXi / detJ;\\n  const inv10 = -xEta / detJ;\\n  const inv11 = xXi / detJ;\\n  const dX = new Float64Array(4);\\n  const dY = new Float64Array(4);\\n  for (let i = 0; i < 4; i++) {\\n    dX[i] = inv00 * dXi[i] + inv01 * dEta[i];\\n    dY[i] = inv10 * dXi[i] + inv11 * dEta[i];\\n  }\\n  return {\\n    N, dXi, dEta, dX, dY, detJ,\\n    jacobian: [[xXi, yXi], [xEta, yEta]],\\n    inverseJacobian: [[inv00, inv01], [inv10, inv11]],\\n  };\\n}\\n\\nfunction planeStressMatrix(E, nu) {\\n  const c = E / (1 - nu * nu);\\n  return [\\n    new Float64Array([c, c * nu, 0]),\\n    new Float64Array([c * nu, c, 0]),\\n    new Float64Array([0, 0, c * (1 - nu) / 2]),\\n  ];\\n}\\n\\n/**\\n * Local shell matrices use physical local rotations [rx, ry, rz].\\n * Kirchhoff-compatible slopes are betaX=ry and betaY=-rx, so\\n * gamma_xz=w,x+ry and gamma_yz=w,y-rx.\\n */\\nfunction shellStrainMatrices(geometry) {\\n  const { N, dX, dY } = geometry;\\n  const Bm = zeros(3, 24);\\n  const Bb = zeros(3, 24);\\n  const Bs = zeros(2, 24);\\n  const Bd = zeros(1, 24);\\n  for (let i = 0; i < 4; i++) {\\n    const b = 6 * i;\\n    Bm[0][b] = dX[i];\\n    Bm[1][b + 1] = dY[i];\\n    Bm[2][b] = dY[i];\\n    Bm[2][b + 1] = dX[i];\\n\\n    Bb[0][b + 4] = dX[i];\\n    Bb[1][b + 3] = -dY[i];\\n    Bb[2][b + 3] = -dX[i];\\n    Bb[2][b + 4] = dY[i];\\n\\n    Bs[0][b + 2] = dX[i];\\n    Bs[0][b + 4] = N[i];\\n    Bs[1][b + 2] = dY[i];\\n    Bs[1][b + 3] = -N[i];\\n\\n    // rz - 0.5*(v,x-u,y): preserves rigid in-plane rotation.\\n    Bd[0][b] = 0.5 * dY[i];\\n    Bd[0][b + 1] = -0.5 * dX[i];\\n    Bd[0][b + 5] = N[i];\\n  }\\n  return { Bm, Bb, Bs, Bd };\\n}\\n\\nfunction covariantShearRow(localXY, xi, eta, direction) {\\n  const geometry = q4Geometry(localXY, xi, eta);\\n  const { Bs } = shellStrainMatrices(geometry);\\n  const [[xXi, yXi], [xEta, yEta]] = geometry.jacobian;\\n  const ax = direction === 'xi' ? xXi : xEta;\\n  const ay = direction === 'xi' ? yXi : yEta;\\n  const row = new Float64Array(24);\\n  for (let i = 0; i < 24; i++) row[i] = ax * Bs[0][i] + ay * Bs[1][i];\\n  return row;\\n}\\n\\n/**\\n * MITC4 assumed transverse shear matrix. Covariant shear is sampled at the\\n * four midside tying points A(0,-1), B(1,0), C(0,1), D(-1,0), interpolated,\\n * then transformed back to the local Cartesian axes at the integration point.\\n */\\nfunction mitc4ShearMatrix(localXY, xi, eta) {\\n  const gammaXiA = covariantShearRow(localXY, 0, -1, 'xi');\\n  const gammaXiC = covariantShearRow(localXY, 0, 1, 'xi');\\n  const gammaEtaD = covariantShearRow(localXY, -1, 0, 'eta');\\n  const gammaEtaB = covariantShearRow(localXY, 1, 0, 'eta');\\n  const assumedXi = new Float64Array(24);\\n  const assumedEta = new Float64Array(24);\\n  for (let i = 0; i < 24; i++) {\\n    assumedXi[i] = 0.5 * ((1 - eta) * gammaXiA[i] + (1 + eta) * gammaXiC[i]);\\n    assumedEta[i] = 0.5 * ((1 - xi) * gammaEtaD[i] + (1 + xi) * gammaEtaB[i]);\\n  }\\n  const geometry = q4Geometry(localXY, xi, eta);\\n  const [[inv00, inv01], [inv10, inv11]] = geometry.inverseJacobian;\\n  const Bs = zeros(2, 24);\\n  for (let i = 0; i < 24; i++) {\\n    Bs[0][i] = inv00 * assumedXi[i] + inv01 * assumedEta[i];\\n    Bs[1][i] = inv10 * assumedXi[i] + inv11 * assumedEta[i];\\n  }\\n  return Bs;\\n}\\n\\nfunction addBtDB(K, B, D, scale) {\\n  const n = K.length;\\n  const m = B.length;\\n  const DB = zeros(m, n);\\n  for (let a = 0; a < m; a++) {\\n    for (let j = 0; j < n; j++) {\\n      let value = 0;\\n      for (let b = 0; b < m; b++) value += D[a][b] * B[b][j];\\n      DB[a][j] = value;\\n    }\\n  }\\n  for (let i = 0; i < n; i++) {\\n    for (let j = 0; j < n; j++) {\\n      let value = 0;\\n      for (let a = 0; a < m; a++) value += B[a][i] * DB[a][j];\\n      K[i][j] += scale * value;\\n    }\\n  }\\n}\\n\\nfunction addOuter(K, row, scale) {\\n  for (let i = 0; i < row.length; i++) {\\n    if (row[i] === 0) continue;\\n    for (let j = 0; j < row.length; j++) {\\n      if (row[j] !== 0) K[i][j] += scale * row[i] * row[j];\\n    }\\n  }\\n}\\n\\nfunction blockTransformation(frame) {\\n  const T = zeros(24);\\n  const R = [frame.ex, frame.ey, frame.ez];\\n  for (let node = 0; node < 4; node++) {\\n    const base = 6 * node;\\n    for (let block = 0; block < 2; block++) {\\n      const offset = base + 3 * block;\\n      for (let i = 0; i < 3; i++) {\\n        for (let j = 0; j < 3; j++) T[offset + i][offset + j] = R[i][j];\\n      }\\n    }\\n  }\\n  return T;\\n}\\n\\nfunction congruence(Klocal, T) {\\n  const n = Klocal.length;\\n  const KT = zeros(n);\\n  const result = zeros(n);\\n  for (let i = 0; i < n; i++) {\\n    for (let k = 0; k < n; k++) {\\n      const value = Klocal[i][k];\\n      if (value === 0) continue;\\n      for (let j = 0; j < n; j++) KT[i][j] += value * T[k][j];\\n    }\\n  }\\n  for (let i = 0; i < n; i++) {\\n    for (let k = 0; k < n; k++) {\\n      const value = T[k][i];\\n      if (value === 0) continue;\\n      for (let j = 0; j < n; j++) result[i][j] += value * KT[k][j];\\n    }\\n  }\\n  return result;\\n}\\n\\nfunction transformVector(T, vector) {\\n  const result = new Float64Array(T.length);\\n  for (let i = 0; i < T.length; i++) {\\n    for (let j = 0; j < vector.length; j++) result[i] += T[i][j] * vector[j];\\n  }\\n  return result;\\n}\\n\\nfunction transformVectorTranspose(T, vector) {\\n  const result = new Float64Array(T.length);\\n  for (let i = 0; i < T.length; i++) {\\n    for (let j = 0; j < vector.length; j++) result[i] += T[j][i] * vector[j];\\n  }\\n  return result;\\n}\\n\\n/** Return the 24x24 stiffness of a planar four-node shell in global axes. */\\nfunction shell4Stiffness(nodes, material) {\\n  checkShellInput(nodes, material);\\n  const frame = shellLocalFrame(nodes, material.planarityTolerance ?? 1e-5);\\n  const { E, nu, t } = material;\\n  const shearCorrection = material.shearCorrection ?? (5 / 6);\\n  const drillFactor = material.drillFactor ?? 1e-3;\\n  const D0 = planeStressMatrix(E, nu);\\n  const G = E / (2 * (1 + nu));\\n  const Ds = [\\n    new Float64Array([shearCorrection * G * t, 0]),\\n    new Float64Array([0, shearCorrection * G * t]),\\n  ];\\n  const Klocal = zeros(24);\\n  const points = [-GAUSS, GAUSS];\\n  let area = 0;\\n\\n  for (const xi of points) {\\n    for (const eta of points) {\\n      const geometry = q4Geometry(frame.localXY, xi, eta);\\n      const { Bm, Bb, Bd } = shellStrainMatrices(geometry);\\n      const Bs = mitc4ShearMatrix(frame.localXY, xi, eta);\\n      area += geometry.detJ;\\n      addBtDB(Klocal, Bm, D0, t * geometry.detJ);\\n      addBtDB(Klocal, Bb, D0, (t ** 3 / 12) * geometry.detJ);\\n      addBtDB(Klocal, Bs, Ds, geometry.detJ);\\n      addOuter(Klocal, Bd[0], drillFactor * E * t * geometry.detJ);\\n    }\\n  }\\n\\n  const T = blockTransformation(frame);\\n  const K = congruence(Klocal, T);\\n  return {\\n    K, Klocal, T, frame, area,\\n    diagnostics: { shearCorrection, shearInterpolation: 'MITC4', drillFactor },\\n  };\\n}\\n\\n/** Consistent pressure load. Positive pressure acts along the element local +z. */\\nfunction shell4PressureLoad(nodes, pressure) {\\n  const frame = shellLocalFrame(nodes);\\n  const local = new Float64Array(24);\\n  for (const xi of [-GAUSS, GAUSS]) {\\n    for (const eta of [-GAUSS, GAUSS]) {\\n      const geometry = q4Geometry(frame.localXY, xi, eta);\\n      for (let i = 0; i < 4; i++) local[6 * i + 2] += pressure * geometry.N[i] * geometry.detJ;\\n    }\\n  }\\n  return transformVectorTranspose(blockTransformation(frame), local);\\n}\\n\\n/** Invert the Q4 map and return bilinear load weights for a global point. */\\nfunction mapPointToShell4(nodes, point, tolerance = 1e-7) {\\n  const frame = shellLocalFrame(nodes);\\n  const p = Array.isArray(point) ? point : toPoint(point);\\n  const delta = sub(p, frame.origin);\\n  const targetX = dot(delta, frame.ex);\\n  const targetY = dot(delta, frame.ey);\\n  const distance = dot(delta, frame.ez);\\n  let xi = 0, eta = 0;\\n  let converged = false;\\n  for (let iteration = 0; iteration < 15; iteration++) {\\n    const geometry = q4Geometry(frame.localXY, xi, eta);\\n    let x = 0, y = 0;\\n    for (let i = 0; i < 4; i++) {\\n      x += geometry.N[i] * frame.localXY[i][0];\\n      y += geometry.N[i] * frame.localXY[i][1];\\n    }\\n    const rx = x - targetX;\\n    const ry = y - targetY;\\n    const [[xXi, yXi], [xEta, yEta]] = geometry.jacobian;\\n    const det = xXi * yEta - xEta * yXi;\\n    const dXi = (yEta * rx - xEta * ry) / det;\\n    const dEta = (-yXi * rx + xXi * ry) / det;\\n    xi -= dXi;\\n    eta -= dEta;\\n    if (Math.hypot(dXi, dEta) < 1e-11) {\\n      converged = true;\\n      break;\\n    }\\n  }\\n  const inside = converged && Math.abs(xi) <= 1 + tolerance && Math.abs(eta) <= 1 + tolerance;\\n  return {\\n    inside, xi, eta, distance,\\n    N: q4Shape(xi, eta).N,\\n    frame,\\n  };\\n}\\n\\n/** Distribute a global force vector at a point to the four translational nodes. */\\nfunction shell4PointLoad(nodes, point, force) {\\n  const mapped = mapPointToShell4(nodes, point);\\n  if (!mapped.inside) return null;\\n  const result = new Float64Array(24);\\n  for (let i = 0; i < 4; i++) {\\n    result[6 * i] = mapped.N[i] * force[0];\\n    result[6 * i + 1] = mapped.N[i] * force[1];\\n    result[6 * i + 2] = mapped.N[i] * force[2];\\n  }\\n  return { load: result, mapping: mapped };\\n}\\n\\nfunction multiply(A, vector) {\\n  const result = new Float64Array(A.length);\\n  for (let i = 0; i < A.length; i++) {\\n    for (let j = 0; j < vector.length; j++) result[i] += A[i][j] * vector[j];\\n  }\\n  return result;\\n}\\n\\nfunction vonMisesPlaneStress(stress) {\\n  const [sx, sy, txy] = stress;\\n  return Math.sqrt(sx * sx - sx * sy + sy * sy + 3 * txy * txy);\\n}\\n\\n/** Recover membrane/bending stresses at 2x2 points and the element center. */\\nfunction shell4Response(nodes, material, uGlobal) {\\n  if (uGlobal.length !== 24) throw new Error('shell4Response expects 24 global DOFs');\\n  const element = shell4Stiffness(nodes, material);\\n  return shell4ResponseFromElement(element, material, uGlobal);\\n}\\n\\n/** Recover response while reusing already-assembled element geometry. */\\nfunction shell4ResponseFromElement(element, material, uGlobal) {\\n  if (uGlobal.length !== 24) throw new Error('shell4ResponseFromElement expects 24 global DOFs');\\n  const uLocal = transformVector(element.T, uGlobal);\\n  const D0 = planeStressMatrix(material.E, material.nu);\\n  const G = material.E / (2 * (1 + material.nu));\\n  const shearCorrection = material.shearCorrection ?? (5 / 6);\\n  const samples = [\\n    [-GAUSS, -GAUSS], [GAUSS, -GAUSS],\\n    [GAUSS, GAUSS], [-GAUSS, GAUSS], [0, 0],\\n  ];\\n  const points = [];\\n  let maxVonMises = 0;\\n  for (const [xi, eta] of samples) {\\n    const geometry = q4Geometry(element.frame.localXY, xi, eta);\\n    const { Bm, Bb } = shellStrainMatrices(geometry);\\n    const Bs = mitc4ShearMatrix(element.frame.localXY, xi, eta);\\n    const membraneStrain = multiply(Bm, uLocal);\\n    const curvature = multiply(Bb, uLocal);\\n    const shearStrain = multiply(Bs, uLocal);\\n    const topStrain = new Float64Array(3);\\n    const bottomStrain = new Float64Array(3);\\n    for (let i = 0; i < 3; i++) {\\n      topStrain[i] = membraneStrain[i] + 0.5 * material.t * curvature[i];\\n      bottomStrain[i] = membraneStrain[i] - 0.5 * material.t * curvature[i];\\n    }\\n    const topStress = multiply(D0, topStrain);\\n    const bottomStress = multiply(D0, bottomStrain);\\n    const transverseShear = new Float64Array([\\n      shearCorrection * G * shearStrain[0],\\n      shearCorrection * G * shearStrain[1],\\n    ]);\\n    const vonMisesTop = vonMisesPlaneStress(topStress);\\n    const vonMisesBottom = vonMisesPlaneStress(bottomStress);\\n    const transverseShearMagnitude = Math.hypot(...transverseShear);\\n    maxVonMises = Math.max(maxVonMises, vonMisesTop, vonMisesBottom);\\n    points.push({\\n      xi, eta, membraneStrain, curvature, shearStrain,\\n      topStress, bottomStress, transverseShear,\\n      transverseShearMagnitude, vonMisesTop, vonMisesBottom,\\n    });\\n  }\\n  return { ...element, uLocal, points, center: points[4], maxVonMises };\\n}\\n\\nfunction assembleShellModel(model) {\\n  const ndof = model.nodes.length * DOF_PER_NODE;\\n  const K = zeros(ndof);\\n  const elementData = [];\\n  for (const element of model.elements) {\\n    if (element.type && element.type !== 'shell4') continue;\\n    const indices = element.nodes ?? [element.n1, element.n2, element.n3, element.n4];\\n    if (indices.length !== 4) throw new Error(`element ${element.id ?? '?'} needs four nodes`);\\n    const nodes = indices.map((index) => model.nodes[index]);\\n    const material = model.properties[element.group] ?? model.properties.default;\\n    if (!material) throw new Error(`no material for shell group ${element.group}`);\\n    const data = shell4Stiffness(nodes, material);\\n    const dofs = indices.flatMap((index) =>\\n      Array.from({ length: DOF_PER_NODE }, (_, d) => DOF_PER_NODE * index + d));\\n    for (let i = 0; i < 24; i++) {\\n      for (let j = 0; j < 24; j++) K[dofs[i]][dofs[j]] += data.K[i][j];\\n    }\\n    elementData.push({ element, indices, nodes, material, dofs, ...data });\\n  }\\n  return { K, ndof, elementData };\\n}\\n\\nfunction applyNodalLoads(F, loads = []) {\\n  for (const load of loads) {\\n    const base = DOF_PER_NODE * load.node;\\n    const values = [load.fx, load.fy, load.fz, load.mx, load.my, load.mz];\\n    for (let d = 0; d < DOF_PER_NODE; d++) F[base + d] += Number(values[d] ?? 0);\\n  }\\n  return F;\\n}\\n\\nfunction constrainedDofs(supports = []) {\\n  const fixed = new Set();\\n  for (const support of supports) {\\n    const base = DOF_PER_NODE * support.node;\\n    for (let d = 0; d < DOF_PER_NODE; d++) {\\n      if (support[DOF_NAMES[d]]) fixed.add(base + d);\\n    }\\n  }\\n  return [...fixed].sort((a, b) => a - b);\\n}\\n\\n/** Factor the unconstrained symmetric positive-definite system once. */\\nfunction factorConstrainedSystem(K, fixedDofs, pivotTolerance = 1e-13) {\\n  const fixed = new Set(fixedDofs);\\n  const free = Array.from({ length: K.length }, (_, i) => i).filter((i) => !fixed.has(i));\\n  const n = free.length;\\n  const L = zeros(n);\\n  let maxDiag = 0;\\n  for (let i = 0; i < n; i++) maxDiag = Math.max(maxDiag, Math.abs(K[free[i]][free[i]]));\\n  const floor = Math.max(maxDiag * pivotTolerance, EPS);\\n  for (let i = 0; i < n; i++) {\\n    for (let j = 0; j <= i; j++) {\\n      let sum = K[free[i]][free[j]];\\n      for (let k = 0; k < j; k++) sum -= L[i][k] * L[j][k];\\n      if (i === j) {\\n        if (!(sum > floor)) {\\n          throw new Error(`shell system is singular/indefinite at reduced DOF ${i}: ${sum}`);\\n        }\\n        L[i][j] = Math.sqrt(sum);\\n      } else {\\n        L[i][j] = sum / L[j][j];\\n      }\\n    }\\n  }\\n  return { L, free, totalDofs: K.length };\\n}\\n\\nfunction solveFactoredSystem(factor, F) {\\n  const { L, free, totalDofs } = factor;\\n  const n = free.length;\\n  const y = new Float64Array(n);\\n  const x = new Float64Array(n);\\n  for (let i = 0; i < n; i++) {\\n    let sum = F[free[i]];\\n    for (let j = 0; j < i; j++) sum -= L[i][j] * y[j];\\n    y[i] = sum / L[i][i];\\n  }\\n  for (let i = n - 1; i >= 0; i--) {\\n    let sum = y[i];\\n    for (let j = i + 1; j < n; j++) sum -= L[j][i] * x[j];\\n    x[i] = sum / L[i][i];\\n  }\\n  const U = new Float64Array(totalDofs);\\n  for (let i = 0; i < n; i++) U[free[i]] = x[i];\\n  return U;\\n}\\n\\nfunction elementDisplacements(U, dofs) {\\n  return Float64Array.from(dofs, (dof) => U[dof]);\\n}\\n\\nglobalThis.PlateShell={DOF_PER_NODE,DOF_NAMES,zeros,vecZeros,shellLocalFrame,q4Shape,q4Geometry,shellStrainMatrices,mitc4ShearMatrix,transformVector,transformVectorTranspose,shell4Stiffness,shell4PressureLoad,mapPointToShell4,shell4PointLoad,shell4Response,shell4ResponseFromElement,assembleShellModel,applyNodalLoads,constrainedDofs,factorConstrainedSystem,solveFactoredSystem,elementDisplacements};\\n})();\\n\\n/* SI units. Flat MITC4 plate; in-plane and drilling DOFs suppressed only because\\n   this linear flat transverse-load problem is uncoupled. No cracking or curvature. */\\n(()=>{'use strict';\\nconst S=globalThis.PlateShell;\\nfunction model(p,spans){\\n  const {n,L,B,E,nu,t}=p,ny=n,nx=spans*n,nodes=[],elements=[],supports=[];\\n  const id=(i,j)=>j*(nx+1)+i;\\n  for(let j=0;j<=ny;j++)for(let i=0;i<=nx;i++){\\n    nodes.push({x:i*L/n,y:j*B/ny,z:0});\\n    supports.push({node:id(i,j),ux:true,uy:true,rz:true,uz:i%n===0||(p.edgeSupport==='simple'&&(j===0||j===ny))});\\n  }\\n  for(let j=0;j<ny;j++)for(let i=0;i<nx;i++)elements.push({id:elements.length,type:'shell4',group:'plate',nodes:[id(i,j),id(i+1,j),id(i+1,j+1),id(i,j+1)]});\\n  const m={nodes,elements,supports,properties:{plate:{E,nu,t}}},a=S.assembleShellModel(m),F=new Float64Array(a.ndof);\\n  for(const e of a.elementData){\\n    const x=e.nodes.reduce((v,k)=>v+k.x,0)/4,y=e.nodes.reduce((v,k)=>v+k.y,0)/4;\\n    if(p.load==='wheels'){\\n      const ex0=e.nodes[0].x,ex1=e.nodes[1].x,ey0=e.nodes[0].y,ey1=e.nodes[3].y;\\n      for(const wheel of wheels(p)){\\n        const a=Math.max(ex0,wheel.x-.175),b=Math.min(ex1,wheel.x+.175),c=Math.max(ey0,wheel.y-.125),d=Math.min(ey1,wheel.y+.125);\\n        if(b<=a||d<=c)continue;\\n        // Integrate the actual rectangular contact overlap using 2x2 Gauss quadrature.\\n        for(const gx of [-1/Math.sqrt(3),1/Math.sqrt(3)])for(const gy of [-1/Math.sqrt(3),1/Math.sqrt(3)]){\\n          const point=[(a+b)/2+gx*(b-a)/2,(c+d)/2+gy*(d-c)/2,0],force=-wheel.force/(.35*.25)*(b-a)*(d-c)/4;\\n          const f=S.shell4PointLoad(e.nodes,point,[0,0,force]).load;e.dofs.forEach((dof,k)=>F[dof]+=f[k]);\\n        }\\n      }\\n      continue;\\n    }\\n    const x0=p.patchX*L,y0=p.patchY*B;\\n    const pressure=p.load==='uniform'?p.p:(x>x0&&x<x0+L/2&&y>y0&&y<y0+B/2?4*p.p:0);\\n    const f=S.shell4PressureLoad(e.nodes,-pressure);\\n    e.dofs.forEach((d,k)=>F[d]+=f[k]);\\n  }\\n  return {m,a,F,nx,ny,id,fixed:S.constrainedDofs(supports)};\\n}\\nfunction solve(o,values=new Map()){\\n  const fixed=[...new Set([...o.fixed,...values.keys()])],rhs=o.F.slice();\\n  for(let i=0;i<rhs.length;i++)for(const [d,v] of values)rhs[i]-=o.a.K[i][d]*v;\\n  const U=S.solveFactoredSystem(S.factorConstrainedSystem(o.a.K,fixed),rhs);\\n  for(const [d,v] of values)U[d]=v;\\n  const R=o.F.map((v,i)=>o.a.K[i].reduce((sum,k,j)=>sum+k*U[j],-v));\\n  const fixedSet=new Set(fixed); let freeResidual=0,total=0,reaction=0,momentLoad=0,momentReaction=0,zeroError=0;\\n  for(let i=0;i<U.length;i++){\\n    if(!fixedSet.has(i))freeResidual=Math.max(freeResidual,Math.abs(R[i]));\\n    else zeroError=Math.max(zeroError,Math.abs(U[i]-(values.get(i)||0)));\\n    if(i%6===2){total+=o.F[i];reaction+=R[i];momentLoad+=o.m.nodes[(i-2)/6].x*o.F[i];momentReaction+=o.m.nodes[(i-2)/6].x*R[i];}\\n    if(i%6===4){momentLoad-=o.F[i];momentReaction-=R[i];}\\n  }\\n  return {...o,U,R,checks:{appliedForce:total,appliedFirstMomentX:momentLoad,forceRelative:Math.abs(total+reaction)/Math.max(1,Math.abs(total)),momentRelative:Math.abs(momentLoad+momentReaction)/Math.max(1,Math.abs(momentLoad)),freeResidualRelative:freeResidual/Math.max(1,Math.abs(total)),prescribedError:zeroError}};\\n}\\nfunction beam(p){\\n  const {n,L,B,E,t}=p,h=L/n,EI=E*B*t**3/12,K=S.zeros(2*(n+1)),F=new Float64Array(2*(n+1));\\n  for(let i=0;i<n;i++){\\n    const k=[[12,6*h,-12,6*h],[6*h,4*h*h,-6*h,2*h*h],[-12,-6*h,12,-6*h],[6*h,2*h*h,-6*h,4*h*h]],x=(i+.5)*h;\\n    const q=p.load==='uniform'?p.p*B:(x>p.patchX*L&&x<(p.patchX+.5)*L?2*p.p*B:0),f=p.load==='wheels'?[0,0,0,0]:[-q*h/2,-q*h*h/12,-q*h/2,q*h*h/12];\\n    if(p.load==='wheels')for(const wheel of wheels(p)){\\n      const a=Math.max(i*h,wheel.x-.175),b=Math.min((i+1)*h,wheel.x+.175);if(b<=a)continue;\\n      for(const [g,weight] of [[-Math.sqrt(3/5),5/9],[0,8/9],[Math.sqrt(3/5),5/9]]){\\n        const xx=(a+b)/2+g*(b-a)/2,r=(xx-i*h)/h,N=[1-3*r*r+2*r*r*r,h*(r-2*r*r+r*r*r),3*r*r-2*r*r*r,h*(-r*r+r*r*r)];\\n        for(let k=0;k<4;k++)f[k]-=N[k]*wheel.force/.35*(b-a)/2*weight;\\n      }\\n    }\\n    for(let a=0;a<4;a++){F[2*i+a]+=f[a];for(let b=0;b<4;b++)K[2*i+a][2*i+b]+=EI/h**3*k[a][b];}\\n  }\\n  const U=S.solveFactoredSystem(S.factorConstrainedSystem(K,[0,2*n]),F);\\n  return Array.from({length:n+1},(_,i)=>U[2*i]);\\n}\\nfunction wheels(p){return [-(p.track??1.4)/2,(p.track??1.4)/2].flatMap(dx=>[-(p.axle??1.5)/2,(p.axle??1.5)/2].map(dy=>({x:p.carX+dx,y:(p.carY??p.B/2)+dy,force:p.wheelForce})));}\\nfunction run(options={}){\\n  const p={L:4,B:3,t:.16,E:30e9,nu:.2,p:10000,n:8,load:'uniform',patchX:.25,patchY:0,carX:2,wheelForce:30000,edgeSupport:'free',...options};\\n  if(![4,8,12,16].includes(p.n)||p.B<=0||p.E<=0||p.t<=0||p.nu<0||p.nu>=.5)throw Error('Invalid plate parameters');\\n  const full=solve(model(p,2)),single=model(p,1),values=new Map();\\n  // Transfer the solved cut-edge rotations. w is already zero at the support line.\\n  for(let j=0;j<=p.n;j++)for(const d of [3,4])values.set(6*single.id(p.n,j)+d,full.U[6*full.id(p.n,j)+d]);\\n  const retained=solve(single,values),simple=solve(single),bw=beam(p);\\n  let wError=0,wMax=0,rotationError=0,cutMoment=0;\\n  for(let j=0;j<=p.n;j++)for(let i=0;i<=p.n;i++){\\n    const a=6*single.id(i,j),b=6*full.id(i,j);\\n    wError=Math.max(wError,Math.abs(retained.U[a+2]-full.U[b+2]));wMax=Math.max(wMax,Math.abs(full.U[b+2]));\\n    for(const d of [3,4])rotationError=Math.max(rotationError,Math.abs(retained.U[a+d]-full.U[b+d]));\\n  }\\n  for(let j=0;j<=p.n;j++)cutMoment+=retained.R[6*single.id(p.n,j)+4];\\n  function compact(o){const girder=Array(o.nx/p.n+1).fill(0),diaphragm=[0,0];for(let j=0;j<=o.ny;j++)for(let i=0;i<=o.nx;i++){const force=o.R[6*o.id(i,j)+2];if(i%p.n===0)girder[i/p.n]+=force;else if(p.edgeSupport==='simple'&&(j===0||j===o.ny))diaphragm[j===0?0:1]+=force;}return {reactions:{girder,diaphragm},nx:o.nx,ny:o.ny,w:o.m.nodes.map((_,i)=>o.U[6*i+2]),checks:o.checks};}\\n  return {p,full:compact(full),retained:compact(retained),simple:compact(simple),beam:bw,cutMoment,interfaceError:wError/Math.max(wMax,1e-15),interfaceRotationError:rotationError,wheels:p.load==='wheels'?wheels(p):[]};\\n}\\nglobalThis.PlateChain={run,beam};\\n})();\\n\\nself.onmessage=({data})=>{try{\\n const {id,kind,p}=data;\\n if(kind==='scan'){\\n   let best=null;const samples=[];\\n   for(const patchX of [0,.125,.25,.375,.5])for(const patchY of [0,.25,.5]){\\n     const r=PlateChain.run({...p,n:8,load:'patch',patchX,patchY});\\n     const w=r.full.w[2*17+4]; // fixed point: x=L/2, y=B/4 on 2-span 16x8 grid\\n     const item={patchX,patchY,w};samples.push(item);if(!best||w<best.w)best=item;\\n   }\\n   self.postMessage({id,kind,best,samples});\\n }else self.postMessage({id,kind,result:PlateChain.run(p)});\\n}catch(e){self.postMessage({id:data.id,error:e.message});}};\\n\";\n"}, {"name": "scripts/three-src/fem-workbench.js", "text": "import * as THREE from '../../interactive/vendor/three.module.js';\nimport {OrbitControls} from '../../interactive/vendor/controls/OrbitControls.js';\nimport {physicalDeck,installStoryUI} from './deck-story-view.js';\nimport {installExplorer} from './deck-explorer.js';\nimport {installPlayUI} from './deck-play-ui.js';\ninstallStoryUI();let overview=true,story=true,revealed=false,storyCase='continuous',physical=null,storyLabels=[],carDrag=false;\nconst $=id=>document.getElementById(id),sceneEl=$('scene'),scene=new THREE.Scene();scene.background=new THREE.Color('#e8eeef');\nconst renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));sceneEl.prepend(renderer.domElement);\nconst camera=new THREE.PerspectiveCamera(42,1,.01,200),controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.target.set(4,0,-1.5);\nscene.add(new THREE.HemisphereLight(0xffffff,0x445766,2));const sun=new THREE.DirectionalLight(0xffffff,1.5);sun.position.set(3,8,5);scene.add(sun);\nconst surfaceGroup=new THREE.Group();scene.add(surfaceGroup);const marker=new THREE.Mesh(new THREE.SphereGeometry(.075,14,10),new THREE.MeshBasicMaterial({color:0xda3a73}));scene.add(marker);\nlet result=null,selected={x:1.2,y:3.6},mesh=null,seq=0,pending=false,mode='full',activeTask=0,baseline=null,prepared=false,wasPicked=false,records=[],completed=new Set(),history=[],timer,scanBest=null;\nconst blobURL=URL.createObjectURL(new Blob([window.PLATE_WORKER_SOURCE],{type:'text/javascript'})),worker=new Worker(blobURL);URL.revokeObjectURL(blobURL);\nconst requests=new Map();function compute(kind,p){return new Promise((resolve,reject)=>{const id=++seq;requests.set(id,{resolve,reject});worker.postMessage({id,kind,p});});}\nworker.onmessage=({data})=>{const r=requests.get(data.id);if(!r)return;requests.delete(data.id);data.error?r.reject(Error(data.error)):r.resolve(data);};worker.onerror=e=>{$('status').textContent='求解线程出错：'+e.message;for(const r of requests.values())r.reject(Error(e.message));requests.clear();};\nfunction parameters(){if(story)return {L:2.4,B:7.2,t:.22,E:34e9,track:1.62,axle:2.916,carY:+$('carY').value,nu:.2,n:16,load:'wheels',p:10000,carX:+$('carX').value,wheelForce:+$('wheelForce').value,edgeSupport:storyCase.endsWith('four')?'simple':'free'};let n=+$('mesh').value;const load=$('load').value;if(load==='patch'&&![8,16].includes(n)){$('mesh').value=String(n>=12?16:8);n=+$('mesh').value;}const pressure=+$('pressure').value;if(!Number.isFinite(pressure)||pressure<2||pressure>20)throw Error('基准压力范围为 2–20 kPa');return {B:+$('width').value,nu:+$('nu').value,n,load,p:pressure*1000,patchX:+$('patchX').value,patchY:+$('patchY').value};}\nfunction signature(p,omit=[]){return JSON.stringify(['B','nu','n','load','p','patchX','patchY'].filter(k=>!omit.includes(k)).map(k=>p[k]));}\nfunction defaults(){for(const [id,value] of Object.entries({mode:'full',load:'uniform',pressure:'10',width:'3',nu:'0.2',mesh:'8',patchX:'0.25',patchY:'0',scale:'100'}))$(id).value=value;mode='full';selected={x:2,y:.75};$('scaleOut').textContent='100×';}\nfunction current(){return result?.[mode];}function nodeIndex(o=current()){const n=result.p.n,i=Math.max(0,Math.min(o.nx,Math.round(selected.x/result.p.L*n))),j=Math.max(0,Math.min(n,Math.round(selected.y/result.p.B*n)));return j*(o.nx+1)+i;}\nfunction sample(){return current().w[nodeIndex()];}function targetW(r=result){return r.full.w[(r.p.n/4)*(2*r.p.n+1)+r.p.n/2];}\nfunction clear(){surfaceGroup.traverse(o=>{o.geometry?.dispose();if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material?.dispose();});surfaceGroup.clear();for(const x of storyLabels)x.el.remove();storyLabels=[];}\nfunction color(w){return new THREE.Color('#f5f5f5').lerp(new THREE.Color(w<0?'#2266ae':'#b45524'),Math.min(1,Math.abs(w)/.012));}\nfunction coord(i,j,o){return new THREE.Vector3(i*result.p.L/result.p.n,+$('scale').value*o.w[j*(o.nx+1)+i],-j*result.p.B/result.p.n);}\nfunction line(points,c=0x6c8087){const g=new THREE.BufferGeometry().setFromPoints(points),l=new THREE.Line(g,new THREE.LineBasicMaterial({color:c}));surfaceGroup.add(l);return l;}\nfunction rebuild(){if(!result)return;if(story){if(overview||!revealed)$('scale').value='0';else if($('autoShape').checked){const peak=Math.max(...current().w.map(Math.abs));$('scale').value=String(Math.min(100000,Math.max(10,Math.round(.32/Math.max(peak,1e-12)/10)*10)));}$('scaleOut').textContent=$('scale').value+'×';}clear();const o=current(),n=result.p.n,positions=[],colors=[],indices=[];\n for(let j=0;j<=n;j++)for(let i=0;i<=o.nx;i++){const k=j*(o.nx+1)+i,v=coord(i,j,o),c=story?new THREE.Color('#d6cebc').lerp(new THREE.Color(o.w[k]<0?'#2879b4':'#d07835'),Math.abs(o.w[k])>=.1*Math.max(...o.w.map(Math.abs))?Math.min(1,Math.abs(o.w[k])/Math.max(...o.w.map(Math.abs),1e-12)):0):color(o.w[k]);positions.push(v.x,v.y,v.z);colors.push(c.r,c.g,c.b);}\n for(let j=0;j<n;j++)for(let i=0;i<o.nx;i++){const a=j*(o.nx+1)+i,b=a+1,c=a+o.nx+1,d=c+1;indices.push(a,c,b,b,c,d);}\n const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));g.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));g.setIndex(indices);g.computeVertexNormals();mesh=new THREE.Mesh(g,new THREE.MeshBasicMaterial({vertexColors:!story||$('showColors').checked,color:story&&!$('showColors').checked?0xd6cebc:0xffffff,side:THREE.DoubleSide}));surfaceGroup.add(mesh);if(!story||$('showMesh').checked)surfaceGroup.add(new THREE.LineSegments(new THREE.WireframeGeometry(g),new THREE.LineBasicMaterial({color:0x53656b,transparent:true,opacity:.28})));\n if(story){physical=physicalDeck(surfaceGroup,result,mode,(i,j)=>coord(i,j,o),overview);for(const label of physical.labels){const el=document.createElement('span');el.className='scene-label '+label.kind;el.textContent=label.text;sceneEl.append(el);storyLabels.push({...label,el});}readouts();window.dispatchEvent(new Event('deck:update'));globalThis.FEMWorkbench.debug={p:result.p,mode,selected:{...selected},w:sample(),version:seq};return;}\n for(let i=0;i<=o.nx;i+=n){const a=new THREE.Vector3(i*4/n,0,0),b=new THREE.Vector3(i*4/n,0,-result.p.B);line([a,b],0x243b4d);for(const y of [0,result.p.B]){const support=new THREE.Mesh(new THREE.ConeGeometry(.13,.28,4),new THREE.MeshStandardMaterial({color:0x657d88}));support.position.set(i*4/n,-.14,-y);surfaceGroup.add(support);}}\n // Undeformed outline remains visible; only presentation coordinates are amplified.\n line([new THREE.Vector3(0,0,0),new THREE.Vector3(o.nx*4/n,0,0),new THREE.Vector3(o.nx*4/n,0,-result.p.B),new THREE.Vector3(0,0,-result.p.B),new THREE.Vector3(0,0,0)],0x324958);\n const q=result.p,xx=q.load==='patch'?[q.patchX*4+.5,q.patchX*4+1.5]:Array.from({length:o.nx/n*3},(_,i)=>(i+.5)*4/3),ys=q.load==='patch'?[(q.patchY+.125)*q.B,(q.patchY+.375)*q.B]:[q.B*.25,q.B*.75];\n for(const x of xx)for(const y of ys)surfaceGroup.add(new THREE.ArrowHelper(new THREE.Vector3(0,-1,0),new THREE.Vector3(x,.85,-y),.65,0xbc5934,.13,.07));\n readouts();window.dispatchEvent(new Event('deck:update'));globalThis.FEMWorkbench.debug={p:result.p,mode,selected:{...selected},w:sample(),version:seq};\n}\nfunction readouts(){if(!result)return;const o=current(),k=nodeIndex(),i=k%(o.nx+1),j=Math.floor(k/(o.nx+1));selected={x:i*result.p.L/result.p.n,y:j*result.p.B/result.p.n};marker.position.copy(coord(i,j,o));$('node').textContent=`#${k} · x=${selected.x.toFixed(2)}, y=${selected.y.toFixed(2)} m`;$('w').textContent=(sample()*1000).toFixed(4)+' mm';$('min').textContent=(Math.min(...o.w)*1000).toFixed(4)+' mm';$('balance').textContent=o.checks.forceRelative.toExponential(2);$('sceneNote').textContent=`${o.nx*o.ny} 个 MITC4 单元 · 拖动旋转 / 点击节点 · 形状放大 ${$('scale').value}× · 颜色为实际 w，固定色标`;\n if(story){const small=document.querySelectorAll('.readouts small');small[0].textContent='你选中的桥面位置';small[1].textContent='这处桥面怎样移动';small[2].textContent='桥面最多下沉';small[3].textContent=storyCase.startsWith('continuous')?'无车跨的中部':'当前支承方式';$('node').textContent=`x=${selected.x.toFixed(2)}, y=${selected.y.toFixed(2)} m`;$('w').textContent=revealed?`${sample()<0?'↓ 下挠':'↑ 上翘'} ${Math.abs(sample()*1000).toFixed(3)} mm`:'先猜，再看';$('min').textContent=revealed?`${Math.abs(Math.min(...o.w)*1000).toFixed(3)} mm`:'尚未显示变形';const right=result.full.w[(result.p.n/2)*(2*result.p.n+1)+result.p.n*1.5];$('balance').textContent=storyCase.startsWith('continuous')?(revealed?`${right>0?'↑ 上翘':'↓ 下挠'} ${Math.abs(right*1000).toFixed(3)} mm`:'它会怎样？'):(storyCase==='four'?'四条边托住、可转动':'中间切开、左跨简支');$('sceneNote').textContent=`每轮 ${result.p.wheelForce/1000} kN · 四轮共 ${result.p.wheelForce*4/1000} kN · ${revealed?'变形已放大 '+$('scale').value+' 倍':'当前先看原来的形状'} · 拖动车身挪位置`;$('wheelTotal').textContent=`四轮合计 ${result.p.wheelForce*4/1000} kN · 横向车位 ${result.p.carX.toFixed(2)} m · 纵向 ${result.p.carY.toFixed(2)} m`;drawProfile();$('sceneViews').dataset.view=overview?'whole':'local';if($('showColors').checked&&!overview)$('sceneNote').textContent+=' · 蓝下沉/橙上抬；着色区≥本次最大位移的10%';if(overview)$('sceneNote').textContent='整桥位置示意：橙框为局部计算区域。先看车辆位置，再点“放大橙框”。';}else{const labels=['选中节点 · 同一求解数据','该节点 w','全模型节点最小 w','竖向力平衡相对残差'];document.querySelectorAll('.readouts small').forEach((e,i)=>e.textContent=labels[i]);}\n}\nfunction home(type='iso'){camera.zoom=innerWidth<760?(story&&overview?.62:.72):1;camera.updateProjectionMatrix();const B=result?.p.B||3,L=result?.p.L||4,center=mode==='full'?L:L/2;if(story&&overview){controls.target.set(L,0,-4);camera.position.set(17,15,20);}else{controls.target.set(center,0,-B/2);if(type==='top')camera.position.set(center,Math.max(B,2*L)*1.6,-B/2+.001);else if(type==='side')camera.position.set(center,.8,Math.max(B,2*L)*1.6);else camera.position.set(center+6,5,-B/2-7);}controls.update();}\nfunction drawProfile(){const o=current(),n=result.p.n,j=Math.max(0,Math.min(n,Math.round(result.p.carY/result.p.B*n))),values=Array.from({length:o.nx+1},(_,i)=>o.w[j*(o.nx+1)+i]),peak=Math.max(...values.map(Math.abs),1e-12),pts=values.map((w,i)=>`${30+i/o.nx*540},${45-(revealed&&!overview?w/peak*42:0)}`).join(' ');$('plateProfile').hidden=overview||!story;const svg=$('plateProfile').querySelector('svg');svg.innerHTML=`<path d=\"M30 45H570\" stroke=\"#647c87\" stroke-dasharray=\"5 4\"/><polyline points=\"${pts}\" fill=\"none\" stroke=\"#ac522d\" stroke-width=\"3\"/><text x=\"30\" y=\"110\" font-size=\"14\">横向 ${o.nx/n*result.p.L} m · 本截面最大位移 ${(peak*1000).toFixed(4)} mm（竖向单独放大）</text>`;}\n\nfunction updateProgress(){$('progress').textContent=`已核对 ${completed.size}/9 道可自动核对题；第 10 题需教师评价。`;}\nasync function apply(){clearTimeout(timer);if(pending){timer=setTimeout(apply,120);return;}let p;try{p=parameters();}catch(e){$('status').textContent=e.message;return;}pending=true;$('calculate').disabled=true;$('status').textContent='正在求解；可继续旋转查看上次结果…';try{const data=await compute('solve',p);result=data.result;mode=$('mode').value;rebuild();history.push({task:activeTask,p:{...p},w:targetW(),mode,time:new Date().toISOString()});document.body.classList.remove('solve-error');$('status').textContent='结果已更新 · 图形、读数与判题共享同一组节点解';}catch(e){document.body.classList.add('solve-error');$('status').textContent='计算失败：'+e.message;throw e;}finally{pending=false;$('calculate').disabled=false;}}\nconst tasks=[\n ['旋转辨认','把板旋转到不同角度，辨认三条竖向支承线；相机转动不应改变节点位移。'],\n ['点选取样','点击 x=2.00 m、y=0.75 m 的节点，读取同一节点的竖向位移。粉色点表示当前取样位置。'],\n ['显示与物理分开','把显示放大调到 200×，核对节点实际位移仍与准备本题时相同。'],\n ['反求荷载','调整基准压力，使指定节点 x=2 m、y=0.75 m 达到目标下挠；保持几何、边界和其他输入不变。'],\n ['换一种支承方式','改成单独一块两边托住的板。观察同一位置的下沉，再解释相邻板块原来提供了什么作用。'],\n ['逼近梁的极限','选择简支板、ν=0、16×16 网格，对照全宽 Euler–Bernoulli 梁的跨中位移；误差目标小于 1%。'],\n ['网格不是装饰','依次采用 8、12、16 网格计算同一连续板、同一荷载，比较固定点挠度。检验最后两次变化是否小于 2%。'],\n ['寻找最不利位置','固定 x=2 m、y=0.75 m 的下挠为目标，在 15 个允许的面荷载位置中找到最不利布置。只改变面荷载起点，保持总荷载、8×8 网格和其他参数不变。'],\n ['检验线性','把基准压力从 10 调到 20 kPa，核对固定节点位移是否变为两倍，并说明这一结论依赖什么条件。'],\n ['迁移与反例','如果板面有明显曲率，或支承只能受压并发生脱空，当前模型还缺什么？引用一次操作数据，说明你会如何升级模型。此题由教师评价。']\n];\ntasks.forEach((t,i)=>$('task').add(new Option(`${i+1}. ${t[0]}`,String(i))));\nfunction describe(){$('taskTitle').textContent=tasks[activeTask][0];$('taskPrompt').textContent=tasks[activeTask][1];prepared=false;$('feedback').textContent='点击“准备本题”恢复本题基准；避免把其他题的参数带入。';}\nasync function prepare(){if(pending)return;story=false;document.body.classList.remove('story-mode');prepared=false;defaults();history=[];wasPicked=false;scanBest=null;if(activeTask===7)$('load').value='patch';await apply();home();baseline={p:{...result.p},w:targetW(),camera:camera.position.clone()};prepared=true;$('explain').value='';$('feedback').textContent=activeTask===3?`本题目标：${(baseline.w*1.5*1000).toFixed(4)} mm，允许相对误差 0.5%。`:activeTask===7?'面荷载已设定；试着改变起点。核对时会独立遍历允许的 15 个位置。':'基准已准备，请操作后核对。';}\nasync function submit(){if(!prepared||pending){$('feedback').textContent='请先准备本题并等待当前计算完成。';return;}if(signature(parameters())!==signature(result.p)){$('feedback').textContent='参数尚未求解，请等待结果更新。';return;}\n let ok=false,detail='',requiresExplanation=false;const p=result.p,same=omit=>signature(p,omit)===signature(baseline.p,omit),fixedNode=Math.abs(selected.x-2)<1e-8&&Math.abs(selected.y-.75)<1e-8,w=targetW();\n switch(activeTask){\n case 0:ok=camera.position.distanceTo(baseline.camera)>2&&same([])&&mode==='full'&&Math.abs(w-baseline.w)<1e-12;detail='相机改变，物理参数与固定点位移保持不变。';break;\n case 1:ok=wasPicked&&fixedNode&&mode==='full'&&same([]);detail='节点的坐标、编号与位移来自同一份结果。';break;\n case 2:ok=+$('scale').value===200&&same([])&&mode==='full'&&Math.abs(w-baseline.w)<1e-12;detail='显示放大不参与刚度矩阵或力向量。';break;\n case 3:ok=same(['p'])&&mode==='full'&&Math.abs(w/(baseline.w*1.5)-1)<=.005;detail=`固定点当前 ${(w*1000).toFixed(4)} mm；目标 ${(baseline.w*1.5*1000).toFixed(4)} mm。`;break;\n case 4:ok=same([])&&mode==='simple'&&Math.abs(sample())>Math.abs(baseline.w)&&fixedNode;detail='改为单独一块两边托住的板后，当前工况下观察点的下沉增大。';break;\n case 5:{const eb=result.beam[p.n/2],err=Math.abs(sample()/eb-1);ok=same(['nu','n'])&&p.nu===0&&p.n===16&&mode==='simple'&&fixedNode&&err<.01;detail=`与梁跨中位移的相对差 ${(err*100).toFixed(3)}%。板的剪切效应和离散误差仍然存在。`;break;}\n case 6:{const found=[8,12,16].map(n=>history.filter(h=>h.p.n===n&&signature(h.p,['n'])===signature(baseline.p,['n'])).at(-1));ok=found.every(Boolean)&&mode==='full'&&same(['n'])&&p.n===16&&Math.abs(found[1].w/found[2].w-1)<.02;detail=found.every(Boolean)?`12→16 网格固定点位移变化 ${(Math.abs(found[1].w/found[2].w-1)*100).toFixed(3)}%。收敛不能证明边界假设正确。`:'需要分别计算 8、12、16 网格并保留相同输入。';break;}\n case 7:if(!same(['patchX','patchY'])||p.n!==8||mode!=='full'){detail='本题只允许移动面荷载；请恢复本题的几何、压力、边界和网格。';break;}pending=true;$('submit').disabled=true;$('feedback').textContent='正在独立遍历 15 个位置；旋转与缩放仍可使用…';try{const scan=await compute('scan',baseline.p);scanBest=scan;const gap=Math.abs((w-scan.best.w)/scan.best.w);ok=gap<=.002;detail=`当前 ${(w*1000).toFixed(4)} mm；15 个位置中的最小值 ${(scan.best.w*1000).toFixed(4)} mm，差 ${(gap*100).toFixed(2)}%。${ok?'达到本题离散搜索目标。':'继续比较跨中附近与偏载侧。'}`;}finally{pending=false;$('submit').disabled=false;}break;\n case 8:ok=same(['p'])&&p.p===20000&&mode==='full'&&Math.abs(w/baseline.w-2)<1e-8;detail=`位移比 ${(w/baseline.w).toFixed(6)}。解释应指出小变形、线弹性和边界状态不变。`;break;\n case 9:requiresExplanation=true;detail=$('explain').value.trim().length>=20?'已记录解释，等待教师按“变化的假设—所需模型—操作证据”评价。':'请补充解释和一次操作数据；不能只写“使用更细网格”。';break;\n }\n if(ok)completed.add(activeTask);records.push({task:activeTask+1,automatic:!requiresExplanation,passed:requiresExplanation?null:ok,detail,p:{...p},mode,selected:{...selected},w:sample(),fixedPointW:w,explanation:$('explain').value,scan:activeTask===7?scanBest:null});$('feedback').textContent=(requiresExplanation?'':ok?'核对通过。':'尚未通过。')+detail;updateProgress();\n}\nfunction pointerRay(e){const r=renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);return ray;}\nlet down=null;renderer.domElement.addEventListener('pointerdown',e=>{down={x:e.clientX,y:e.clientY};if(story&&physical&&pointerRay(e).intersectObjects(physical.pick)[0]){carDrag=true;controls.enabled=false;renderer.domElement.setPointerCapture(e.pointerId);}},true);\nrenderer.domElement.addEventListener('pointermove',e=>{if(!carDrag)return;const v=new THREE.Vector3();if(pointerRay(e).ray.intersectPlane(new THREE.Plane(new THREE.Vector3(0,1,0),0),v)){$('carX').value=String(Math.max(1,Math.min(1.4,Math.round(v.x*20)/20)));physical.car.position.x=+$('carX').value;$('status').textContent='车位预览；松开后更新桥面响应。';}});\nrenderer.domElement.addEventListener('pointerup',e=>{if(carDrag){carDrag=false;controls.enabled=true;apply().catch(()=>{});return;}if(!result||!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>5)return;const hit=pointerRay(e).intersectObject(mesh)[0];if(hit){selected={x:hit.point.x,y:-hit.point.z};wasPicked=true;rebuild();}});\nrenderer.domElement.addEventListener('pointercancel',()=>{carDrag=false;controls.enabled=true;});\nsceneEl.addEventListener('keydown',e=>{const offset=camera.position.clone().sub(controls.target);if(['ArrowLeft','ArrowRight'].includes(e.key)){offset.applyAxisAngle(new THREE.Vector3(0,1,0),e.key==='ArrowLeft'?.15:-.15);camera.position.copy(controls.target).add(offset);}else if(['+','=','-'].includes(e.key))camera.position.copy(controls.target).add(offset.multiplyScalar(e.key==='-'?1.12:.88));else if(['ArrowUp','ArrowDown'].includes(e.key))camera.position.y+=e.key==='ArrowUp'?.6:-.6;else return;e.preventDefault();controls.update();});\n$('home').onclick=()=>home();$('top').onclick=()=>home('top');$('side').onclick=()=>home('side');$('fullscreen').onclick=async()=>{try{await sceneEl.requestFullscreen();}catch{$('status').textContent='当前浏览器不允许全屏；可继续使用嵌入视图。';}};\n$('scale').oninput=()=>{if(story)$('autoShape').checked=false;$('scaleOut').textContent=$('scale').value+'×';rebuild();};$('mode').onchange=()=>{mode=$('mode').value;rebuild();home();};\nfor(const id of ['load','pressure','width','nu','mesh','patchX','patchY'])$(id).oninput=()=>{$('status').textContent='输入已变化，正在准备更新结果…';clearTimeout(timer);timer=setTimeout(()=>apply().catch(()=>{}),300);};\n$('calculate').onclick=()=>apply().catch(()=>{});$('task').onchange=()=>{activeTask=+$('task').value;describe();};$('start').onclick=()=>prepare().catch(e=>$('feedback').textContent=e.message);$('submit').onclick=()=>submit().catch(e=>$('feedback').textContent=e.message);\n$('save').onclick=()=>{const data={schema:'bridge-fem-workbench/v1',solver:'flat MITC4 linear elastic',displayScale:+$('scale').value,camera:camera.position.toArray(),records,history,current:result?{p:result.p,mode,selected,w:sample(),checks:current().checks}:null,currentExplanation:$('explain').value};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='有限元实验_操作证据.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};\nnew ResizeObserver(()=>{const w=sceneEl.clientWidth,h=sceneEl.clientHeight;camera.aspect=w/h;camera.zoom=innerWidth<760?(story&&overview?.62:.72):1;camera.updateProjectionMatrix();renderer.setSize(w,h,false);}).observe(sceneEl);\nglobalThis.FEMWorkbench={get overview(){return overview},get result(){return result},get records(){return records},get history(){return history},get busy(){return pending},get scan(){return scanBest},project(x,y){if(!result)return null;const o=current(),i=Math.round(x/result.p.L*result.p.n),j=Math.round(y/result.p.B*result.p.n),v=coord(i,j,o).project(camera),r=renderer.domElement.getBoundingClientRect();return {x:r.left+(v.x+1)*r.width/2,y:r.top+(1-v.y)*r.height/2};}};\nfunction enterStory(){story=true;revealed=false;storyCase='continuous';document.body.classList.add('story-mode');$('mode').value='full';$('scale').value='0';$('scaleOut').textContent='0×';$('carX').value='1.2';$('carY').value='3.6';$('wheelForce').value='30000';apply().then(()=>home()).catch(()=>{});}\n$('expert').onclick=()=>{story=false;document.body.classList.remove('story-mode');defaults();apply().then(()=>home()).catch(()=>{});};$('backStory').onclick=enterStory;\n$('reveal').onclick=()=>{if(overview){overview=false;revealed=false;home();}revealed=!revealed;$('reveal').textContent=revealed?'对照：看看原来的形状':'显示变形，开始试';$('scale').value=revealed?'120':'0';$('scaleOut').textContent=revealed?'120×':'0×';$('storyHint').textContent='现在可以挪车、换车重或换连接方式。记下一个方案，再试另一个。';rebuild();};\ndocument.querySelectorAll('[data-guess]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-guess]').forEach(x=>x.classList.toggle('chosen',x===b));$('storyHint').textContent='先保留这个猜想，再显示桥面变形。';});\ndocument.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{overview=false;storyCase=b.dataset.case;document.querySelectorAll('[data-case]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));$('mode').value=storyCase.startsWith('continuous')?'full':'simple';revealed=true;$('reveal').textContent='对照：看看原来的形状';$('scale').value='120';$('scaleOut').textContent='120×';$('storyHint').textContent=storyCase.startsWith('continuous')?'同一辆车，同一整块板。观察左右两跨。':storyCase==='cut'?'中间开一道缝。车没变，左跨的下挠会怎样变？':'先与断开后的左跨比较：同样的车位、车重，加上两道横隔板会怎样？';$('supportNote').textContent=storyCase.startsWith('continuous')?'三道主梁提供竖向约束；板连续跨过中梁。两侧边自由，不是四边固结。':storyCase==='cut'?'两块板在中梁处断开，左跨两边托住、另外两边自由。右跨无车且不再随左跨一起弯曲。':'两侧主梁与两道横隔板托住单块板。本例把四边简化为竖向支承，边缘可转动；未计算横隔板自身的柔度，不是四边固结。';if(storyCase==='continuous-four'){$('storyHint').textContent='两块板仍连在中间主梁上，同时两端有横隔板。可以与连续、无横隔板的方案比较。';$('supportNote').textContent='三道主梁与两道横隔板共同提供竖向支承；中间主梁上板仍连续。横隔板自身柔度未建模。';}apply().then(()=>home()).catch(()=>{});});\nfor(const id of ['carX','carY','wheelForce'])$(id).oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>apply().catch(()=>{}),180);};\nfor(const [id,dx] of [['carLeft',-.05],['carRight',.05]])$(id).onclick=()=>{$('carX').value=String(Math.max(1,Math.min(1.4,Math.round((+$('carX').value+dx)*20)/20)));apply().catch(()=>{});};\nfor(const id of ['showMesh','showColors','showTransfer','showDimensions'])$(id).onchange=rebuild;\n$('underneath').onclick=()=>{overview=false;rebuild();camera.position.set(9,-4,8);controls.target.set(mode==='full'?result.p.L:result.p.L/2,0,-result.p.B/2);controls.update();};\n$('wholeBridge').onclick=()=>{overview=true;rebuild();home();};$('localPlate').onclick=()=>{overview=false;rebuild();home();};$('hideVehicle').onchange=rebuild;$('autoShape').onchange=rebuild;\n$('scale').max='100000';$('scale').step='10';\ninstallExplorer({state:()=>({result,mode,case:storyCase,revealed,busy:pending,dirty:result&&(result.p.carX!==+$('carX').value||result.p.carY!==+$('carY').value||result.p.wheelForce!==+$('wheelForce').value||(result.p.edgeSupport==='simple')!==(storyCase.endsWith('four')))}),solve:async p=>(await compute('solve',p)).result,change:async s=>{if(pending)return;$('carX').value=String(s.carX);$('carY').value=String(s.carY??3.6);$('wheelForce').value=String(s.wheelForce);document.querySelector(`[data-case=\"${s.case}\"]`).click();}});\ninstallPlayUI({state:()=>({result,mode,overview,revealed})});\ndescribe();updateProgress();home();$('scale').value='0';$('scaleOut').textContent='0×';apply().catch(()=>{});\nconst leaders=document.createElementNS('http://www.w3.org/2000/svg','svg');leaders.id='labelLeaders';sceneEl.append(leaders);\nfunction frame(){requestAnimationFrame(frame);controls.update();const placed=[];leaders.replaceChildren();for(const label of storyLabels){const p=label.at.clone().project(camera),W=sceneEl.clientWidth,H=sceneEl.clientHeight;label.el.style.display=p.z>1||p.z< -1?'none':'block';if(p.z>1||p.z< -1)continue;const ax=(p.x*.5+.5)*W,ay=(-p.y*.5+.5)*H,w=label.el.offsetWidth,h=label.el.offsetHeight;let x=Math.max(w/2+5,Math.min(W-w/2-5,ax)),y=Math.max(h+5,Math.min(H-45,ay));for(let tries=0;tries<20;tries++){if(!placed.some(r=>Math.abs(x-r.x)<(w+r.w)/2+5&&Math.abs(y-h/2-r.y+r.h/2)<(h+r.h)/2+5))break;y-=h+7;if(y<h+5){x=Math.max(w/2+5,Math.min(W-w/2-5,x+w+8));y=Math.min(H-45,ay+h+10);}}placed.push({x,y,w,h});label.el.style.left=x+'px';label.el.style.top=y+'px';if(Math.hypot(x-ax,y-ay)>7){const line=document.createElementNS(leaders.namespaceURI,'line');for(const [k,v] of Object.entries({x1:ax,y1:ay,x2:x,y2:y,stroke:'#667f89','stroke-width':1}))line.setAttribute(k,String(v));leaders.append(line);}}renderer.render(scene,camera);}frame();\n"}, {"name": "scripts/three-src/deck-story-view.js", "text": "import * as THREE from '../../interactive/vendor/three.module.js';\nimport {vehicleAsset} from './vehicle-asset-data.js';\nexport function physicalDeck(group,result,mode,point,overview=false){\n const q=result.p,o=result[mode],length=o.nx/q.n*q.L,B=q.B,labels=[],pick=[];\n function box(parent,x,y,z,sx,sy,sz,c,opacity=1){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),new THREE.MeshStandardMaterial({color:c,roughness:.8,transparent:opacity<1,opacity}));m.position.set(x,y,z);parent.add(m);return m;}\n // The girders illustrate the vertical support lines used by the plate model.\n function girder(x,z,len,alongX=false){const g=new THREE.Group();g.position.set(x,-.43,z);if(alongX)g.rotation.y=Math.PI/2;group.add(g);box(g,0,0,0,.13,.5,len,0x527784);box(g,0,.25,0,.5,.1,len,0x789aa5);box(g,0,-.25,0,.5,.1,len,0x789aa5);}\n for(let x=0;x<=length+.001;x+=q.L)girder(x,-B/2,B+.5);\n if(mode==='simple'&&q.edgeSupport!=='simple'){box(group,1.5*q.L+.025,-q.t/2,-B/2,q.L-.05,q.t,B,0xd6cebc);girder(2*q.L,-B/2,B+.5);labels.push({text:'断开的右跨 · 无轮载',at:new THREE.Vector3(1.5*q.L,0,-B/2),kind:'edge'});}\n if(q.edgeSupport==='simple'){\n  // Transverse diaphragms have a different physical role and appearance from main girders.\n  for(const z of [0,-B])box(group,length/2,-.43,z,length,.58,.14,0xb28d62);\n  labels.push({text:'横隔板',at:new THREE.Vector3(length/2,-.6,0),kind:'support'});\n }\n // Give the flat shell an identifiable slab thickness; side faces follow nodal w.\n const perimeter=[];for(let i=0;i<=o.nx;i++)perimeter.push(point(i,0));for(let j=1;j<=q.n;j++)perimeter.push(point(o.nx,j));for(let i=o.nx-1;i>=0;i--)perimeter.push(point(i,q.n));for(let j=q.n-1;j>=0;j--)perimeter.push(point(0,j));\n const side=[];for(let i=0;i<perimeter.length;i++){const a=perimeter[i],b=perimeter[(i+1)%perimeter.length],c=a.clone().add(new THREE.Vector3(0,-q.t,0)),d=b.clone().add(new THREE.Vector3(0,-q.t,0));for(const v of [a,b,c,b,d,c])side.push(v.x,v.y,v.z);}\n const sg=new THREE.BufferGeometry();sg.setAttribute('position',new THREE.Float32BufferAttribute(side,3));sg.computeVertexNormals();group.add(new THREE.Mesh(sg,new THREE.MeshStandardMaterial({color:0xc2b7a4,side:THREE.DoubleSide})));\n labels.push({text:q.edgeSupport==='simple'?(mode==='full'?'三道主梁':'两侧主梁'):'主梁托住板',at:new THREE.Vector3(length,-.5,-B*.6),kind:'support'});\n labels.push({text:q.edgeSupport==='simple'?(mode==='full'?'连续板 · 两端有横隔板':'四边简支教学模型'):'这里是自由边',at:new THREE.Vector3(length*.35,0,0),kind:'edge'});\n if(mode==='simple'&&q.edgeSupport!=='simple')labels.push({text:'两块板在这里分开',at:new THREE.Vector3(q.L,0,-B/2),kind:'cut'});\n\n function guide(a,b,text){if(!document.getElementById('showDimensions')?.checked)return;const geo=new THREE.BufferGeometry().setFromPoints([a,b]);group.add(new THREE.Line(geo,new THREE.LineBasicMaterial({color:0x945f28})));for(const v of [a,b]){const g=new THREE.BufferGeometry().setFromPoints([v.clone().add(new THREE.Vector3(0,.09,0)),v.clone().add(new THREE.Vector3(0,-.09,0))]);group.add(new THREE.Line(g,new THREE.LineBasicMaterial({color:0x945f28})));}labels.push({text,at:a.clone().lerp(b,.5),kind:'dimension'});}\n for(let x=0;x<length-.01;x+=q.L)guide(new THREE.Vector3(x,.08,.45),new THREE.Vector3(x+q.L,.08,.45),'主梁间距 2.40 m');\n guide(new THREE.Vector3(length+.45,.08,0),new THREE.Vector3(length+.45,.08,-B),'沿行车方向取 7.20 m');\n if(document.getElementById('showDimensions')?.checked)labels.push({text:'板厚 0.22 m',at:new THREE.Vector3(0,-q.t/2,-B*.5),kind:'dimension'});\n\n if(!overview){\n const near=q.carX-q.track/2,far=q.carX+q.track/2;\n guide(new THREE.Vector3(0,.06,-(q.carY??B/2)),new THREE.Vector3(near,.06,-(q.carY??B/2)),`左轮到主梁 ${near.toFixed(2)} m`);\n guide(new THREE.Vector3(far,.06,-(q.carY??B/2)),new THREE.Vector3(q.L,.06,-(q.carY??B/2)),`右轮到主梁 ${(q.L-far).toFixed(2)} m`);\n if(q.edgeSupport==='simple'&&document.getElementById('showDimensions')?.checked)labels.push({text:'两道横隔板间距 7.20 m',at:new THREE.Vector3(-.4,.1,-B/2),kind:'dimension'});\n if(document.getElementById('showTransfer')?.checked)o.reactions.girder.forEach((r,i)=>labels.push({text:`主梁 ${i+1}：${(r/1000).toFixed(1)} kN`,at:new THREE.Vector3(i*q.L,-.65,-B*.5),kind:'reaction'}));\n }\n if(document.getElementById('showTransfer')?.checked&&!overview&&q.edgeSupport==='simple')labels.push({text:`横隔板支承合计 ${(o.reactions.diaphragm.reduce((a,b)=>a+b,0)/1000).toFixed(1)} kN`,at:new THREE.Vector3(length/2,-.6,-B),kind:'reaction'});\n if(overview){\n  // Context only: show where the analyzed patch sits on a 20 m teaching bridge.\n  const W=2*q.L;box(group,W/2,-2.5,-4,32,.08,10,0x73adb4);for(const z of [9,-17])box(group,W/2,-2.4,z,32,.3,16,0xb6c5a5);for(let z=-13;z<6;z+=1.5)box(group,q.L,.025,z,.07,.012,.65,0xf1ead6);\n  box(group,W/2,-q.t/2,3,W,q.t,6,0x9caeb4);box(group,W/2,-q.t/2,-10.6,W,q.t,6.8,0x9caeb4);\n  if(mode==='simple')box(group,1.5*q.L,-q.t/2,-B/2,q.L,q.t,B,0x9caeb4);\n  for(const x of [-.3,W+.3]){box(group,x,-q.t/2,-4,.6,q.t,20,0x9caeb4);box(group,x,.35,-4,.09,.7,20,0x55717c);}\n  for(const x of [0,q.L,2*q.L])girder(x,-4,20);\n  for(const z of [5.5,-13.5]){box(group,W/2,-1.05,z,W+.8,.65,.55,0x74858a);for(const x of [.6,W-.6])box(group,x,-2.2,z,.6,2,.65,0x9ba8a9);}\n  const outline=[new THREE.Vector3(0,.035,0),new THREE.Vector3(length,.035,0),new THREE.Vector3(length,.035,-B),new THREE.Vector3(0,.035,-B),new THREE.Vector3(0,.035,0)];group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(outline),new THREE.LineBasicMaterial({color:0xe28e30})));\n  labels.length=0;labels.push({text:'橙框：取这块桥面来看',at:new THREE.Vector3(length/2,.1,0),kind:'dimension'},{text:'整桥示意 · 20 m',at:new THREE.Vector3(W/2,0,-13.5),kind:'dimension'});\n }\n const car=new THREE.Group();group.add(car);car.position.x=q.carX;\n function height(x,y){const i=Math.max(0,Math.min(o.nx,Math.round(x/q.L*q.n))),j=Math.max(0,Math.min(q.n,Math.round(y/B*q.n)));return point(i,j).y;}\n const base=height(q.carX,q.carY??B/2);car.position.y=base;\n for(const part of vehicleAsset){\n  const wheel=part.name.startsWith('wheel-'),cx=part.center[0]*1.8,cy=(q.carY??B/2)+(part.center[2]-.2)*1.8;\n  const shift=wheel?height(q.carX+cx,cy)-base:0,positions=[],colors=[];\n  for(let i=0;i<part.positions.length;i+=3){positions.push(part.positions[i]*1.8,part.positions[i+1]*1.8+shift,-(q.carY??B/2)-(part.positions[i+2]-.2)*1.8);const c=new THREE.Color().setRGB(...part.colors.slice(i,i+3)).convertSRGBToLinear();colors.push(c.r,c.g,c.b);}\n  const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));geometry.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geometry.computeVertexNormals();\n  const m=new THREE.Mesh(geometry,new THREE.MeshStandardMaterial({vertexColors:true,roughness:.75,side:THREE.DoubleSide}));m.name='kenney-'+part.name;car.add(m);pick.push(m);\n }\n for(const w of result.wheels){\n  const z=-w.y,h=height(w.x,w.y);\n  const contact=box(car,w.x-q.carX,h+.013-base,z,.35,.018,.25,0xe36f42,.85);pick.push(contact);\n  if(overview)continue;\n  const arrowLength=1.6+.4*w.force/30000,arrow=new THREE.ArrowHelper(new THREE.Vector3(0,-1,0),new THREE.Vector3(w.x-q.carX,h+arrowLength+.07-base,z),arrowLength,0xba4c2e,.16,.07);for(const m of [arrow.line.material,arrow.cone.material]){m.depthTest=false;}arrow.renderOrder=3;car.add(arrow);\n  labels.push({text:`↓ ${(w.force/1000).toFixed(0)} kN`,at:new THREE.Vector3(w.x,h+arrowLength+.13,w.y*-1),kind:'load'});\n }\n if(document.getElementById('hideVehicle')?.checked&&!overview)car.children.filter(x=>x.name.startsWith('kenney-')).forEach(x=>x.visible=false);\n return {car,pick,labels};\n}\n\nexport function installStoryUI(){\n document.body.classList.add('story-mode');\n if(new URLSearchParams(location.search).get('lesson')==='planar')document.body.classList.add('plate-introduction');\n const task=document.createElement('div');task.id='storyIntro';task.innerHTML=`<p class=\"story-kicker\">连续桥面板 · 轮载实验</p><h1>车轮向下压，<br>桥面也可能向上翘吗？</h1><p class=\"story-lead\">一整块桥面，跨在三道主梁上。小车停在左跨；右跨没有车。</p><p>右边没有车，它会下沉、不动，还是向上翘？先选一个判断，再显示变形。</p><div class=\"guess\"><button data-guess=\"down\">也往下沉</button><button data-guess=\"still\">几乎不动</button><button data-guess=\"up\">会往上翘</button></div><button id=\"reveal\" class=\"story-primary\">显示变形，核对判断</button><p id=\"storyHint\">可以先旋转，看清车轮和板下面的主梁。</p><div class=\"story-steps\"><button data-case=\"continuous\">① 一整块板</button><button data-case=\"cut\">② 中间断开试试</button><button data-case=\"four\">③ 换成四边托住</button><button data-case=\"continuous-four\">两跨连续，同时设横隔板</button></div><details><summary>为什么这样设场景？</summary><p>根据教材“桥面板、横隔构件与局部受力”设置：桥面板把轮载传给主梁，连续性与边缘约束会改变响应。这里用可看清四轮的小车说明作用位置；参数为教学设置，不对应某辆规范车辆。</p></details><button id=\"expert\" class=\"secondary\">再看计算与 10 个练习 →</button>`;\n document.querySelector('.tasks').prepend(task);\n const panel=document.createElement('div');panel.id='storyControls';panel.innerHTML=`<h2>先只改一件事</h2><label>把小车挪到哪里？<input id=\"carX\" type=\"range\" min=\"1\" max=\"1.4\" step=\"0.05\" value=\"1.2\"></label><div class=\"story-nudge\"><button id=\"carLeft\">← 挪一点</button><button id=\"carRight\">挪一点 →</button></div><p class=\"muted\">也可以直接拖动车身，松开后更新计算。</p><label>每个车轮压多重？<select id=\"wheelForce\"><option value=\"15000\">15 kN / 轮</option><option value=\"30000\" selected>30 kN / 轮</option><option value=\"45000\">45 kN / 轮</option></select></label><p id=\"wheelTotal\">四轮合计 120 kN</p><button id=\"underneath\">看看板下面</button><label class=\"story-check\"><input id=\"showMesh\" type=\"checkbox\"> 叠上计算网格</label><label class=\"story-check\"><input id=\"showColors\" type=\"checkbox\"> 用颜色区分上下变形</label><p id=\"supportNote\">三道主梁提供竖向约束；板连续跨过中梁。两侧边自由，不是四边固结。</p><details><summary>尺寸、边界和荷载</summary><p>跨向 x：主梁间距 2.40 m；沿主梁取 7.20 m 长板段；板厚 0.22 m。车辆等比例缩放：轮距 1.62 m、轴距 2.916 m，为本页教学设置。四个橙色矩形是轮胎接触区。每个接触面 0.35×0.25 m，合力等于该轮读数。E=34 GPa，ν=0.2。主梁在本例中只提供竖向约束，不模拟主梁本身的挠曲。</p><p>本场景采用双向竖向约束。若实际连接脱空，需另设接触条件。车体用于辨认轮位，未求解车辆悬架与动力。</p></details>`;\n document.querySelector('.parameters').prepend(panel);\n const back=document.createElement('button');back.id='backStory';back.textContent='回到小车场景';document.querySelector('.toolbar').append(back);\n const nav=document.createElement('div');nav.id='sceneViews';nav.innerHTML='<button id=\"wholeBridge\">整桥：车在哪里</button><button id=\"localPlate\">放大橙框，看局部板</button>';document.querySelector('.toolbar').prepend(nav);\n const moving=document.createElement('label');moving.innerHTML='沿行车方向挪车 / m<input id=\"carY\" type=\"range\" min=\"1.8\" max=\"5.4\" step=\"0.3\" value=\"3.6\">';document.getElementById('wheelTotal').before(moving);\n const display=document.createElement('div');display.innerHTML='<label class=\"story-check\"><input id=\"showDimensions\" type=\"checkbox\"> 标出尺寸和轮距</label><label class=\"story-check\"><input id=\"autoShape\" type=\"checkbox\" checked> 自动放大，看清弯曲形状</label><label class=\"story-check\"><input id=\"hideVehicle\" type=\"checkbox\"> 隐去车身，只看轮载</label><p class=\"muted\">自动放大时，各方案倍数可能不同。比较变形大小，请看 mm 读数；取消后可用相同倍数比较。</p>';document.getElementById('underneath').after(display);const transfer=document.createElement('div');transfer.innerHTML='<label class=\"story-check\"><input id=\"showTransfer\" type=\"checkbox\"> 看力传给哪道主梁</label><details><summary>怎样从这里想到横向分布？</summary><p>先看轮载位置，再看桥面如何向两侧传力，最后看各道主梁收到多少力。图中反力正值表示向上托板，负值表示连接需要向下拉住板；采用可双向传力的理想约束，未模拟脱空。反力属于本局部板的理想支承线；真实桥梁的横向分配还要让主梁、横隔板一起变形，不能将这里的比例直接作为规范横向分布系数。</p><p>“响应范围”按当前最大竖向位移的10%标示，仅帮助观察远近变化；它不是铺装荷载扩散角，也不是规范有效分布宽度。横隔板存在时，它也分担支承反力。交点反力在本页计入主梁，只是统计分组，不能识别实桥交点在两个构件间的真实分担。</p></details>';display.after(transfer);document.getElementById('showColors').parentElement.lastChild.textContent=' 显示桥面响应范围';\n const basis=document.createElement('details');basis.innerHTML='<summary>这些尺寸从哪里来？</summary><p>教材第4章“任务与教学参数”：主梁间距 2.40 m、板厚 0.220 m、E=34 GPa、ν=0.20。沿桥取 7.20 m（3倍板跨）作为局部范围。</p><p>整桥长20 m、两侧各0.60 m悬臂，以及车辆轮距1.62 m、轴距2.916 m，均为位置演示的教学设置。车辆等比例缩放，不代表规范车辆。</p><p>本实验只施加四轮荷载，总力默认120 kN；教材1 m板带算例另含5.50 kN/m均布作用，不能把两个算例的位移直接视作同一答案。外部整桥不参与这次局部求解。</p><a href=\"../chapters/ch03.html\" target=\"_blank\">查看教材梁桥章</a>';document.getElementById('storyControls').append(basis);\n const profile=document.createElement('div');profile.id='plateProfile';profile.innerHTML='<p>穿过车辆中心的横向截面 · 虚线是原形</p><svg viewBox=\"0 0 600 120\" aria-label=\"板的横向变形剖面\"></svg>';document.querySelector('.visual').append(profile);\n\n}\n"}, {"name": "scripts/three-src/deck-explorer.js", "text": "// Open-ended experiments: snapshots and grading reference the same FE results as the drawing.\nexport function installExplorer(api){\n const $=id=>document.getElementById(id),intro=$('storyIntro');\n intro.querySelector('.story-kicker').textContent='桥面实验场 · 自己选一个问题';\n intro.querySelector('h1').innerHTML='车停在哪里，<br>桥面会有什么不同？';\n intro.querySelector('.story-lead').textContent='拖动车辆，转到桥下面看看。你可以随时换问题，也可以只管试。';\n intro.querySelector('.story-lead').nextElementSibling.remove();\n const chooser=document.createElement('label');chooser.className='mission-picker';chooser.innerHTML='想试什么？<select id=\"mission\"><option value=\"free\">自由试一试</option><option value=\"lift\">哪里停车，另一跨抬起最多？</option><option value=\"support\">加上横隔板，会有什么变化？</option><option value=\"weight\">车重增加，下沉也按比例增加吗？</option></select>';\n intro.querySelector('.guess').before(chooser);\n const mission=document.createElement('div');mission.id='missionCard';mission.innerHTML='<p id=\"missionPrompt\"></p><button id=\"missionCheck\">核对我的尝试</button><p id=\"missionFeedback\" role=\"status\"></p><details id=\"missionHints\"><summary>给我一点提示</summary><p id=\"missionHint\"></p><button id=\"moreHint\">再给一点提示</button></details>';\n intro.querySelector('.story-steps').before(mission);\n intro.querySelector('.story-steps').before(Object.assign(document.createElement('p'),{className:'case-label',textContent:'桥面怎样连接？可以随时切换'}));\n for(const b of intro.querySelectorAll('[data-case]'))b.textContent={continuous:'连着的两跨',cut:'两跨之间断开',four:'单块板 · 两道横隔板','continuous-four':'两跨连续 · 两道横隔板'}[b.dataset.case];\n $('storyControls').querySelector('h2').textContent='这次想怎么试？';\n $('underneath').before(intro.querySelector('.case-label'),intro.querySelector('.story-steps'));\n document.querySelector('[data-case=continuous]').setAttribute('aria-pressed','true');\n const tray=document.createElement('section');tray.id='trialTray';tray.innerHTML='<div class=\"trial-actions\"><button id=\"keepTrial\">记下这个方案</button><button id=\"resetTrial\" class=\"secondary\">恢复最初场景</button></div><p id=\"trialStatus\" role=\"status\">留住一次结果，再换个办法比较。</p><details><summary>我的方案对照 <span id=\"trialCount\">0</span></summary><div class=\"trial-scroll\"><table><thead><tr><th>方案</th><th>车位 x / m</th><th>总重 / kN</th><th>最多下沉 / mm</th><th>无车跨的中部 / mm<br>＋上抬，−下沉</th><th>再试</th></tr></thead><tbody id=\"trials\"></tbody></table></div><button id=\"exportTrials\">导出我的探索记录</button></details>';\n document.querySelector('.visual').append(tray);\n const attribution=document.createElement('p');attribution.className='asset-credit';attribution.innerHTML='车辆外形：<a href=\"https://kenney.nl/assets/car-kit\" target=\"_blank\" rel=\"noopener\">Kenney · CC0</a> · <a href=\"assets/kenney-car/README.md\">来源与改动</a>';document.querySelector('.sources').append(attribution);\n let saved=[],hints=0,checking=false,best=null;const done=new Set();\n const definitions={\n  free:['任选车位、车重和连接方式。记下两个方案，看看哪些变化与你预想的一样。',['先拖住车身横着挪，再松手看读数。','也可以用右侧的左右按钮挪车。换个视角不会改变计算结果。']],\n  lift:['保持两跨连在一起、每轮 30 kN，保持纵向车位3.60 m，只横向挪动车辆。目标：在 9 个允许车位中，让无车跨的中部向上移动得最多。',['先观察无车跨的中部的读数，试着向左和向右各挪一次。','横向每次移动 0.05 m。先找读数变大的方向，再比较相邻位置。']],\n  support:['比较“断开后的左跨”和“加两道横隔板后的单块板”。车位和车重保持相同，各记一个方案，再核对。',['先选“两跨之间断开”，显示变形并记下方案。','再选“单块板 · 加两道横隔板”。看看板下面多了哪两道支承。']],\n  weight:['支承和车位不变，只改每轮重量。分别记下两个不同车重的方案，比较总重量和最多下沉的倍数。',['先记录当前方案，再换一个每轮重量。','用后一次下沉量除以前一次下沉量；总重量也同样相除。']]\n };\n function current(){const s=api.state();if(!s.result)return null;const r=s.result,o=r[s.mode],n=r.p.n;return{case:s.case,carX:r.p.carX,carY:r.p.carY,wheelForce:r.p.wheelForce,down:-Math.min(...o.w)*1000,right:s.case.startsWith('continuous')?r.full.w[(n/2)*(2*n+1)+n*1.5]*1000:null,checks:o.checks,solver:'MITC4, linear elastic, n=16',time:new Date().toISOString()};}\n function ready(){const s=api.state();if(s.busy||s.dirty){$('missionFeedback').textContent='等当前计算更新后再核对。';return false;}return !!s.result;}\n const name=c=>({continuous:'两跨相连',cut:'左跨单独',four:'四边支承','continuous-four':'连续且有横隔板'})[c];\n function render(){ $('trialCount').textContent=String(saved.length);$('trials').replaceChildren();saved.forEach((s,i)=>{const tr=document.createElement('tr');for(const value of [`${i+1} · ${name(s.case)}`,s.carX.toFixed(2),s.wheelForce*4/1000,s.down.toFixed(3),s.right===null?'—':s.right.toFixed(3)]){const td=document.createElement('td');td.textContent=value;tr.append(td);}const td=document.createElement('td'),b=document.createElement('button');b.textContent='恢复';b.setAttribute('aria-label','恢复方案 '+(i+1));b.onclick=()=>api.change(s);td.append(b);tr.append(td);$('trials').append(tr);});}\n $('keepTrial').onclick=()=>{if(!ready())return;if(!api.state().revealed){$('trialStatus').textContent='先点“显示变形”，再记下看到的结果。';return;}if(saved.length>=12){$('trialStatus').textContent='本轮已保留 12 个方案；可先导出，再刷新开始新一轮。';return;}saved.push(current());render();$('trialStatus').textContent=`已记下方案 ${saved.length}。可以换车位、车重或支承，结果留在下面的对照表里。`;};\n $('resetTrial').onclick=()=>api.change({case:'continuous',carX:1.2,carY:3.6,wheelForce:30000});\n function showHint(){const list=definitions[$('mission').value][1];$('missionHint').textContent=list[Math.min(hints,list.length-1)];$('moreHint').hidden=hints>=list.length-1;}\n $('moreHint').onclick=()=>{hints++;showHint();};\n $('mission').onchange=()=>{hints=0;$('missionHints').open=false;const key=$('mission').value;$('missionPrompt').textContent=definitions[key][0];$('missionFeedback').textContent=done.has(key)?'你已经核对过这项；也可以继续找别的例子。':'';$('missionCheck').hidden=key==='free';showHint();};\n $('mission').onchange();\n $('missionCheck').onclick=async()=>{if(checking||!ready())return;const key=$('mission').value,c=current();checking=true;$('missionCheck').disabled=true;try{\n  let message='',ok=false;\n  if(key==='lift'){\n   if(c.case!=='continuous'||c.wheelForce!==30000||c.carY!==3.6){message='这项挑战只比较车位：请恢复“两跨相连”、每轮 30 kN、纵向车位3.60 m。其他问题仍可自由尝试。';}\n   else{if(best===null){$('missionFeedback').textContent='正在用相同条件独立比较 9 个车位…';best=-Infinity;const searchParameters={...api.state().result.p};for(let i=0;i<9;i++){const r=await api.solve({...searchParameters,carX:1+i*.05});const n=r.p.n;best=Math.max(best,r.full.w[(n/2)*(2*n+1)+n*1.5]*1000);}}const gap=(best-c.right)/best;ok=gap<.002;message=ok?`这个车位达到了本题 9 个位置中的最大上抬：${c.right.toFixed(3)} mm。试试解释：车为什么能影响没有车的那一跨？`:`当前无车跨的中部上抬 ${c.right.toFixed(3)} mm，距本题最大值还差 ${(gap*100).toFixed(1)}%。再比较一个相邻车位。`;}\n  }else{\n   let pair=null;for(let i=saved.length-1;i>=0&&!pair;i--)for(let j=i-1;j>=0;j--){const a=saved[j],b=saved[i],sameX=a.carX===b.carX&&a.carY===b.carY;if(key==='support'&&sameX&&a.wheelForce===b.wheelForce&&[a.case,b.case].sort().join()==='cut,four'){pair=a.case==='cut'?[a,b]:[b,a];break;}if(key==='weight'&&sameX&&a.case===b.case&&a.wheelForce!==b.wheelForce){pair=[a,b];break;}}\n   if(!pair)message='还没有一组能直接比较的方案。'+definitions[key][0];\n   else{const [a,b]=pair;ok=true;message=key==='support'?`在相同车位和车重下，最多下沉从 ${a.down.toFixed(3)} 变为 ${b.down.toFixed(3)} mm，减少 ${(100*(1-b.down/a.down)).toFixed(1)}%。再看看两方向怎样一起弯曲。本例把横隔板所在边简化为竖向支承；没有计算横隔板自身的柔度。`:`这组方案的总重量变为 ${(b.wheelForce/a.wheelForce).toFixed(2)} 倍，下沉变为 ${(b.down/a.down).toFixed(2)} 倍。这个比例来自线弹性且支承不变的模型；若开裂或支承脱空，还能这样推吗？`;}\n  }\n  if(ok)done.add(key);if($('mission').value===key){$('missionFeedback').textContent=message;$('missionFeedback').dataset.passed=String(ok);}\n }catch(e){$('missionFeedback').textContent='这次计算没有完成，请重试。'+e.message;best=null;}finally{checking=false;$('missionCheck').disabled=false;}};\n $('exportTrials').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({schema:'bridge-exploration/v1',records:saved,checked:[...done]},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='桥面探索记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};\n document.querySelector('.guess').hidden=true;$('reveal').textContent='显示变形，开始试';$('storyHint').textContent='拖动车身挪位置；空白处拖动旋转。也可以用右侧按钮操作。';\n window.DeckExplorer={get records(){return structuredClone(saved)},get completed(){return [...done]}};\n}\n"}, {"name": "scripts/three-src/deck-play-ui.js", "text": "// Contextual interface: the scene stays visible; only the selected tool is expanded.\nexport function installPlayUI(api){\n if(new URLSearchParams(location.search).get('workbench')==='full')return;\n const $=id=>document.getElementById(id);document.body.classList.add('play-view');\n const visual=document.querySelector('.visual'),scene=$('scene');let opened='',invoker=null;\n const hud=document.createElement('section');hud.id='playHud';hud.innerHTML='<p class=\"play-kicker\">桥面 · 从整桥走近一块板</p><h1 id=\"playTitle\">车下面的桥面，怎样接住重量？</h1><p id=\"playGoal\">先找到橙框：我们将单独观察这块桥面。</p><button id=\"playAction\">走近，看看车下的桥面 →</button><p id=\"playMetric\" role=\"status\"></p>';scene.append(hud);\n const dock=document.createElement('nav');dock.id='playDock';dock.setAttribute('aria-label','探索工具');dock.innerHTML='<button data-drawer=\"move\">挪车</button><button data-drawer=\"connect\">换连接</button><button data-drawer=\"look\">换个看法</button><button data-drawer=\"challenge\">挑个问题</button><button data-drawer=\"trials\">我的方案</button><button id=\"playWhole\">回看整桥</button><button data-drawer=\"notes\">说明与代码</button>';visual.append(dock);\n const drawer=document.createElement('section');drawer.id='playDrawer';drawer.hidden=true;drawer.setAttribute('role','region');drawer.setAttribute('aria-label','当前工具');drawer.innerHTML='<header><strong id=\"drawerTitle\"></strong><button id=\"closeDrawer\" aria-label=\"收起当前工具\">收起 ×</button></header>';visual.append(drawer);\n const panels={};for(const name of ['move','connect','look','challenge','trials','notes']){const p=document.createElement('div');p.dataset.panel=name;p.hidden=true;drawer.append(p);panels[name]=p;}\n const move=panels.move;move.append($('carX').closest('label'),document.querySelector('.story-nudge'),$('carY').closest('label'),$('wheelForce').closest('label'),$('wheelTotal'));\n panels.connect.append(document.querySelector('.story-steps'));const support=document.createElement('details');support.innerHTML='<summary>这些连接有什么区别？</summary>';support.append($('supportNote'));panels.connect.append(support);\n panels.look.append($('hideVehicle').closest('label'),$('showDimensions').closest('label'),$('showColors').closest('label'),$('showTransfer').closest('label'),$('underneath'));\n const presentation=document.createElement('details');presentation.innerHTML='<summary>视角、放大倍数与计算网格</summary>';presentation.append(document.querySelector('.toolbar'),$('autoShape').closest('label'),$('showMesh').closest('label'));panels.look.append(presentation);\n const profile=document.createElement('details');profile.innerHTML='<summary>再看一条横向截面</summary>';profile.append($('plateProfile'));panels.look.append(profile);\n panels.challenge.append(document.querySelector('.mission-picker'),$('missionCard'));\n panels.trials.append($('trialTray'));\n const notes=panels.notes;notes.append(document.querySelector('.readouts'));for(const d of [...$('storyControls').querySelectorAll('details')])notes.append(d);notes.append(document.querySelector('.sources'));const code=document.createElement('a');code.href=location.pathname+'?lesson=planar&workbench=full';code.target='_blank';code.textContent='打开完整实验台与代码';notes.append(code);\n const titles={move:'把车挪到哪里？',connect:'桥面怎样连在一起？',look:'这次想看清什么？',challenge:'挑一个问题，也可以随时换',trials:'留下两个方案，再比较',notes:'需要时再查'};\n function open(name,button){opened=name;invoker=button;drawer.hidden=false;$('drawerTitle').textContent=titles[name];Object.entries(panels).forEach(([key,p])=>p.hidden=key!==name);dock.querySelectorAll('[data-drawer]').forEach(b=>b.setAttribute('aria-expanded',String(b.dataset.drawer===name)));$('closeDrawer').focus();}\n function close(){opened='';drawer.hidden=true;dock.querySelectorAll('[data-drawer]').forEach(b=>b.setAttribute('aria-expanded','false'));invoker?.focus();}\n dock.querySelectorAll('[data-drawer]').forEach(b=>{b.setAttribute('aria-expanded','false');b.onclick=()=>opened===b.dataset.drawer?close():open(b.dataset.drawer,b);});$('closeDrawer').onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!drawer.hidden){e.stopPropagation();close();}});\n $('playWhole').onclick=()=>{$('wholeBridge').click();close();};\n $('playAction').onclick=()=>{const s=api.state();if(s.overview){$('localPlate').click();}else if(!s.revealed){$('reveal').click();}else{$('keepTrial').click();$('playMetric').textContent=$('trialStatus').textContent;}};\n function sync(){const s=api.state();if(!s.result)return;document.body.dataset.sceneStage=s.overview?'whole':'local';$('playTitle').innerHTML=s.overview?'车的重量，<br>怎样传到桥下面？':'挪一挪车，<br>桥面哪里跟着变？';$('playGoal').textContent=s.overview?'先找到橙框：我们将单独观察这块桥面。':s.revealed?'拖动车身挪位置；空白处拖动可旋转。':'轮子压在这里。先看看板会怎样弯曲。';$('playAction').textContent=s.overview?'走近，看看车下的桥面 →':s.revealed?'记下这个方案':'看看桥面怎样弯曲';$('playMetric').textContent=!s.overview&&s.revealed?`最多下沉 ${(-Math.min(...s.result[s.mode].w)*1000).toFixed(3)} mm · 图形放大 ${$('scale').value} 倍`:'';}\n window.addEventListener('deck:update',sync);sync();window.DeckPlay={open,close};\n}\n"}];
